// ---- curves.js ----

// A glyph's outline, as straight lines.
//
// opentype hands back a path of lines and Bézier curves; a solid needs polygons. Each curve is split in half over
// and over until its control points sit within `tolerance` of the straight line between its ends, so a flat curve
// costs two points and a tight one costs as many as it needs. Corners the font really has are never rounded off,
// because only curves are ever split.
//

/** The furthest a point lies from the line between two others. */
function offLine(point, from, to) {
  const dx = to[0] - from[0];
  const dy = to[1] - from[1];
  const length = dx * dx + dy * dy;
  const along = length ? Math.max(0, Math.min(1, ((point[0] - from[0]) * dx + (point[1] - from[1]) * dy) / length)) : 0;
  return Math.hypot(point[0] - from[0] - along * dx, point[1] - from[1] - along * dy);
}

const middle = (a, b) => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];

/** How deep the splitting may go. Twelve halvings is far finer than any printer, and stops a degenerate curve. */
const DEPTH = 12;

/**
 * The closed polygons of an opentype path, in the font's own units with y pointing up.
 *
 * A font measures y downwards, a model upwards, so every y is negated as it is read.
 */
export function flattenPath(path, tolerance = 0.08) {
  const polygons = [];
  const limit = Math.max(0.0005, tolerance);
  let polygon = [];
  let last = [0, 0];

  const append = (point) => {
    last = point;
    polygon.push(point);
  };
  const finish = () => {
    if (polygon.length > 2) polygons.push(polygon);
    polygon = [];
  };

  function quadratic(from, control, to, depth = 0) {
    if (depth >= DEPTH || offLine(control, from, to) <= limit) {
      append(to);
      return;
    }
    const a = middle(from, control);
    const b = middle(control, to);
    const centre = middle(a, b);
    quadratic(from, a, centre, depth + 1);
    quadratic(centre, b, to, depth + 1);
  }

  function cubic(from, first, second, to, depth = 0) {
    if (depth >= DEPTH || Math.max(offLine(first, from, to), offLine(second, from, to)) <= limit) {
      append(to);
      return;
    }
    const a = middle(from, first);
    const b = middle(first, second);
    const c = middle(second, to);
    const ab = middle(a, b);
    const bc = middle(b, c);
    const centre = middle(ab, bc);
    cubic(from, a, ab, centre, depth + 1);
    cubic(centre, bc, c, to, depth + 1);
  }

  for (const command of path.commands) {
    const end = [command.x, -command.y];
    if (command.type === "M") {
      finish();
      append(end);
    } else if (command.type === "L") {
      append(end);
    } else if (command.type === "Q") {
      quadratic(last, [command.x1, -command.y1], end);
    } else if (command.type === "C") {
      cubic(last, [command.x1, -command.y1], [command.x2, -command.y2], end);
    } else if (command.type === "Z") {
      finish();
    }
  }
  finish();
  return polygons;
}

// ---- text.js ----

// What may be typed, and how it is counted.

export const MAX_LINES = 5;
export const MAX_CHARACTERS = 15;

/** One kind of line ending, and no tabs: a tab has no width a font agrees on. */
export const normalizeText = (value) =>
  String(value ?? "")
    .replace(/\r\n?/g, "\n")
    .replace(/\t/g, " ");

/** Lines and characters, counted as the limits count them: a line break is not a character. */
export function textStats(value) {
  const text = normalizeText(value);
  return { lines: text.split("\n").length, characters: [...text.replace(/\n/g, "")].length };
}

/** The text cut down to what will fit, keeping whole characters: an emoji is one, not two. */
export function limitText(value) {
  let remaining = MAX_CHARACTERS;
  return normalizeText(value)
    .split("\n")
    .slice(0, MAX_LINES)
    .map((line) => {
      const characters = [...line].slice(0, remaining);
      remaining -= characters.length;
      return characters.join("");
    })
    .join("\n");
}

// ---- colours.js ----

// Which colour each part is printed in.
//
// The border and base are one colour and the letters another; two more can be given to particular letters, by the
// character or by where it sits, so "NO 7" can have its 7 in red. The colours ride along in the 3MF as its own
// material list, so a slicer opens the file with the parts already assigned.
//

export const DEFAULT_COLOURS = {
  /** One filament for the whole thing, rather than one for the border and another for the letters. */
  single: false,
  border: "#77916a",
  letter: "#f0eedf",
  extras: [
    { enabled: false, targets: "", colour: "#e96868" },
    { enabled: false, targets: "", colour: "#6699dd" },
  ],
};

const hex = (value, fallback) => (/^#[\da-f]{6}$/i.test(value || "") ? value.toLowerCase() : fallback);

export function normalizeColours(value = {}) {
  return {
    single: Boolean(value.single),
    border: hex(value.border, DEFAULT_COLOURS.border),
    letter: hex(value.letter, DEFAULT_COLOURS.letter),
    extras: DEFAULT_COLOURS.extras.map((fallback, i) => ({
      enabled: Boolean(value.extras?.[i]?.enabled),
      targets: String(value.extras?.[i]?.targets ?? "").slice(0, 200),
      colour: hex(value.extras?.[i]?.colour, fallback.colour),
      mode: value.extras?.[i]?.mode === "positions" ? "positions" : "text",
      indices: [...new Set((value.extras?.[i]?.indices || []).filter((n) => Number.isInteger(n) && n >= 0 && n < 100))],
    })),
  };
}

/** The characters an extra colour names, however they were typed: "a,b" and "ab" mean the same. */
export const targetLetters = (value) => [
  ...new Set(
    String(value)
      .split(",")
      .flatMap((token) => [...token.trim()])
      .filter((character) => !/[\s,]/u.test(character)),
  ),
];

const matches = (model, extra) =>
  extra.enabled &&
  (extra.mode === "positions"
    ? extra.indices.includes(model.index)
    : targetLetters(extra.targets).includes(model.char));

/** Which colour a part takes: 0 the border, 1 the letters, 2 and 3 the extras — or 0 throughout in one colour. */
export function colourSlot(model, colours) {
  const settled = normalizeColours(colours);
  if (settled.single || model.kind !== "letter") return 0;
  let slot = 1;
  settled.extras.forEach((extra, i) => {
    if (matches(model, extra)) slot = i + 2;
  });
  return slot;
}

/** The filaments in slot order. In one colour there is only ever the one, so a 3MF lists one material. */
export function palette(colours) {
  const settled = normalizeColours(colours);
  if (settled.single) return [settled.border];
  return [settled.border, settled.letter, ...settled.extras.map((extra) => extra.colour)];
}

/** What the person got wrong: a letter given two colours, or a colour pointed at a letter that isn't there. */
export function colourIssues(
  text,
  colours,
  models = [...text].map((char, index) => ({ char, index, kind: "letter" })),
) {
  const settled = normalizeColours(colours);
  // In one colour nothing is sent anywhere, so there is nothing to clash or to miss.
  if (settled.single) return { duplicates: [], missing: [] };
  const named = settled.extras.map((extra) =>
    extra.enabled && extra.mode !== "positions" ? targetLetters(extra.targets) : [],
  );
  return {
    duplicates: [
      ...new Set(
        models
          .filter(
            (model) => model.char?.trim() && matches(model, settled.extras[0]) && matches(model, settled.extras[1]),
          )
          .map((model) => model.char),
      ),
    ],
    missing: [...new Set(named.flat().filter((character) => !text.includes(character)))],
  };
}

// ---- magnets.js ----

// Magnets sunk into the back of a keyring, so it sticks to a fridge or a toolboard.

/** Sizes magnets are commonly sold in: width across, then thickness, in mm. */
export const MAGNET_SIZES = [
  [2, 1],
  [2, 2],
  [3, 1],
  [4, 1],
  [4, 1.5],
  [5, 1],
  [5, 2],
  [5, 3],
  [6, 2],
  [6, 3],
  [8, 1],
  [8, 2],
  [8, 3],
];

/** The magnets asked for, each brought inside what can actually be made. */
export const normalizeMagnets = (settings) =>
  (Array.isArray(settings.magnets) ? settings.magnets : []).slice(0, 6).map((magnet) => ({
    diameter: Math.max(2, Math.min(8, +magnet.diameter || 6)),
    depth: Math.max(0.5, Math.min(5, +magnet.depth || 2)),
    x: Math.max(-1, Math.min(1, +magnet.x || 0)),
    y: Math.max(-1, Math.min(1, +magnet.y || 0)),
  }));

/** How thick the base has to be to hold the deepest magnet, with material left under it. */
export function magnetMinimum(settings) {
  const magnets = normalizeMagnets(settings);
  if (!settings.magnetEnabled || !magnets.length) return 0.4;
  const deepest = Math.max(...magnets.map((magnet) => magnet.depth));
  const needed = deepest + (+settings.magnetDepthGap || 0) + 0.6 + (settings.magnetMode === "embedded" ? 0.4 : 0);
  return Math.ceil(needed * 10 - 1e-8) / 10;
}

/** The base thickness actually used: the one asked for, or thicker if the magnets need it. */
export function effectiveBase(settings) {
  if (!settings.magnetEnabled || !normalizeMagnets(settings).length) return +settings.base;
  if (settings.magnetAutoHeight !== false) return magnetMinimum(settings);
  return Math.max(+settings.magnetBase || +settings.base, magnetMinimum(settings));
}

// ---- geometry2d.js ----

// Flat geometry the engine leans on: measuring polygons, sliding letters until they touch, finding where the
// pieces of a broken-up outline are nearest each other, and placing a ring hole somewhere it will hold.

/** Twice the area, halved: positive anticlockwise, so a negative one is a hole. */
export const signedArea = (polygon) =>
  polygon.reduce((total, a, i) => {
    const b = polygon[(i + 1) % polygon.length];
    return total + a[0] * b[1] - b[0] * a[1];
  }, 0) / 2;

/** The box round a set of polygons. */
export function bounds(polygons) {
  const min = [Infinity, Infinity];
  const max = [-Infinity, -Infinity];
  for (const polygon of polygons) {
    for (const point of polygon) {
      for (let axis = 0; axis < 2; axis++) {
        if (point[axis] < min[axis]) min[axis] = point[axis];
        if (point[axis] > max[axis]) max[axis] = point[axis];
      }
    }
  }
  return { min, max };
}

export const shiftPolys = (polygons, x, y) => polygons.map((p) => p.map(([px, py]) => [px + x, py + y]));

const edgesOf = (polygons) => polygons.flatMap((p) => p.map((a, i) => [a, p[(i + 1) % p.length]]));

/** Where an edge sits at a height, taking the far side of a horizontal one. */
function atHeight(a, b, y, rightmost) {
  if (Math.abs(a[1] - b[1]) < 1e-9) return rightmost ? Math.max(a[0], b[0]) : Math.min(a[0], b[0]);
  return a[0] + ((y - a[1]) * (b[0] - a[0])) / (b[1] - a[1]);
}

/**
 * How far the second shape has to move right to just touch the first.
 *
 * This is what sets a letter beside its neighbour. Spacing on advance widths alone leaves "AV" looking gapped and
 * "rn" looking joined; sliding the real outlines together until they meet, then adding the gap, spaces by what
 * the letters actually look like. Both shapes are made of straight edges, so each pair reaches its closest at one
 * of the two heights where they overlap — no sampling in between is needed.
 */
export function touchingShift(aPolys, bPolys, fallback = true) {
  let shift = -Infinity;
  for (const [a, b] of edgesOf(aPolys)) {
    for (const [c, d] of edgesOf(bPolys)) {
      const low = Math.max(Math.min(a[1], b[1]), Math.min(c[1], d[1]));
      const high = Math.min(Math.max(a[1], b[1]), Math.max(c[1], d[1]));
      if (low > high + 1e-9) continue;
      for (const y of [low, high]) shift = Math.max(shift, atHeight(a, b, y, true) - atHeight(c, d, y, false));
    }
  }
  if (Number.isFinite(shift)) return shift;
  return fallback ? bounds(aPolys).max[0] - bounds(bPolys).min[0] : -Infinity;
}

/**
 * The shortest links that tie every separate piece of an outline into one.
 *
 * Letters that don't touch leave the keyring in pieces, so a bar is run between them; this works out where each
 * bar should go. It builds a minimum spanning tree over the pieces, comparing each pair once, and compares boxes
 * before points so most pairs are dismissed without looking at them.
 */
export function componentLinks(polygons) {
  if (polygons.length < 2) return [];
  // A long outline is sampled rather than walked point by point: every sample is still on the real contour.
  const sample = (p) => p.filter((_, i) => i % Math.max(1, Math.ceil(p.length / 256)) === 0);
  const shapes = polygons.map((p) => ({ points: sample(p), ...bounds([p]) }));
  const linked = new Set([0]);
  const best = shapes.map(() => ({ d: Infinity }));
  const links = [];
  let newest = 0;

  while (linked.size < shapes.length) {
    const from = shapes[newest];
    for (let b = 0; b < shapes.length; b++) {
      if (linked.has(b)) continue;
      const to = shapes[b];
      const dx = Math.max(0, from.min[0] - to.max[0], to.min[0] - from.max[0]);
      const dy = Math.max(0, from.min[1] - to.max[1], to.min[1] - from.max[1]);
      // Even at their closest the boxes are further apart than the best link found so far.
      if (dx * dx + dy * dy >= best[b].d) continue;
      for (const p of from.points) {
        for (const q of to.points) {
          const d = (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2;
          if (d < best[b].d) best[b] = { d, p, q, b };
        }
      }
    }
    let edge = { d: Infinity };
    for (let b = 0; b < best.length; b++) if (!linked.has(b) && best[b].d < edge.d) edge = best[b];
    if (!edge.q) break;
    links.push(edge);
    linked.add(edge.b);
    newest = edge.b;
  }
  return links;
}

/** The nearest point of a segment to somewhere. */
function onSegment(a, b, x, y) {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const along = Math.max(0, Math.min(1, ((x - a[0]) * dx + (y - a[1]) * dy) / (dx * dx + dy * dy || 1)));
  return [a[0] + along * dx, a[1] + along * dy];
}

/** Whether a point is inside a set of polygons, counting the crossings of a ray going right. */
export function pointInPolys(polygons, x, y) {
  let inside = false;
  for (const polygon of polygons) {
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const a = polygon[i];
      const b = polygon[j];
      if (a[1] > y !== b[1] > y && x < ((b[0] - a[0]) * (y - a[1])) / (b[1] - a[1]) + a[0]) inside = !inside;
    }
  }
  return inside;
}

/** How far a point is from the nearest edge. */
export function distanceToPolys(polygons, x, y) {
  let nearest = Infinity;
  for (const polygon of polygons) {
    for (let i = 0; i < polygon.length; i++) {
      const point = onSegment(polygon[i], polygon[(i + 1) % polygon.length], x, y);
      nearest = Math.min(nearest, Math.hypot(point[0] - x, point[1] - y));
    }
  }
  return nearest;
}

/**
 * Where a ring hole can actually go, given where it was asked for.
 *
 * A ring has to overlap the body enough to hold, and must never eat into a letter. The outline's edges are walked
 * for the nearest place that satisfies both, so dragging a ring slides it along the edge rather than letting it
 * come off or cut through the text.
 */
export function snapHole(outlines, letters, hole, wantedX, wantedY, borderWidth) {
  if (hole.localJoin) return snapLocalHole(outlines, letters, hole, wantedX, wantedY, borderWidth);
  const radius = hole.outer / 2;
  const wall = (hole.outer - hole.inner) / 2;
  const overlap = Math.min(borderWidth * 0.5, wall * 0.45, 0.6);
  const candidates = [];

  for (const polygon of outlines) {
    if (signedArea(polygon) <= 0) continue;
    for (let i = 0; i < polygon.length; i++) {
      const a = polygon[i];
      const b = polygon[(i + 1) % polygon.length];
      const dx = b[0] - a[0];
      const dy = b[1] - a[1];
      const length = Math.hypot(dx, dy);
      if (length < 1e-8) continue;
      const anchor = onSegment(a, b, wantedX, wantedY);
      candidates.push({
        x: anchor[0] + (dy / length) * (radius - overlap),
        y: anchor[1] - (dx / length) * (radius - overlap),
        anchor,
        d: (anchor[0] - wantedX) ** 2 + (anchor[1] - wantedY) ** 2,
      });
    }
  }
  candidates.sort((a, b) => a.d - b.d);
  for (const candidate of candidates) {
    if (pointInPolys(outlines, candidate.x, candidate.y)) continue;
    if (pointInPolys(letters, candidate.x, candidate.y)) continue;
    const clearance = distanceToPolys(letters, candidate.x, candidate.y) - radius;
    if (clearance < 0.02) continue;
    return { ...candidate, clearance };
  }
  throw new Error("There's nowhere safe to put that ring. Widen the border, or make the ring smaller.");
}

/** A ring set into the body rather than hung off it: it may overlap, but never reach a letter. */
function snapLocalHole(outlines, letters, hole, wantedX, wantedY, borderWidth) {
  const radius = hole.outer / 2;
  const wall = (hole.outer - hole.inner) / 2;
  const protect = hole.inner / 2 + 0.3;
  const candidates = [];

  for (const polygon of outlines) {
    if (signedArea(polygon) <= 0) continue;
    for (let i = 0; i < polygon.length; i++) {
      const a = polygon[i];
      const b = polygon[(i + 1) % polygon.length];
      const dx = b[0] - a[0];
      const dy = b[1] - a[1];
      const length = Math.hypot(dx, dy);
      if (length < 1e-8) continue;
      const anchor = onSegment(a, b, wantedX, wantedY);
      const normal = [dy / length, -dx / length];
      const asked = hole.followPointer
        ? radius - ((wantedX - anchor[0]) * normal[0] + (wantedY - anchor[1]) * normal[1])
        : hole.inset;
      const wanted = Math.max(
        Math.min(0.3, wall * 0.3),
        Math.min(wall + borderWidth * 0.5, Number.isFinite(asked) ? asked : wall * 0.9),
      );
      // Pull the ring out of the body a tenth at a time until it clears the letters.
      for (let depth = wanted; depth >= Math.min(0.2, wall * 0.2) - 1e-6; depth -= 0.1) {
        const x = anchor[0] + normal[0] * (radius - depth);
        const y = anchor[1] + normal[1] * (radius - depth);
        if (pointInPolys(letters, x, y) || distanceToPolys(letters, x, y) < protect) continue;
        candidates.push({
          x,
          y,
          anchor,
          normal,
          inset: depth,
          protectedRadius: protect,
          clearance: distanceToPolys(letters, x, y) - hole.inner / 2,
          d: Math.hypot(anchor[0] - wantedX, anchor[1] - wantedY),
        });
        break;
      }
    }
  }
  candidates.sort((a, b) => a.d - b.d);
  if (candidates.length) return candidates[0];
  throw new Error("There's no room to join that ring. Widen the border, or make the ring smaller.");
}

/** Somewhere inside a region, as near as possible to where it was asked for and clear of what's already there. */
export function snapInRegion(polygons, wantedX, wantedY, others = [], radius = 0) {
  const fits = (x, y) =>
    pointInPolys(polygons, x, y) && others.every((o) => Math.hypot(x - o.x, y - o.y) >= radius + o.radius + 0.6);
  if (fits(wantedX, wantedY)) return { x: wantedX, y: wantedY };

  const box = bounds(polygons);
  const points = [];
  for (const polygon of polygons) {
    let cx = 0;
    let cy = 0;
    for (let i = 0; i < polygon.length; i++) {
      const a = polygon[i];
      const b = polygon[(i + 1) % polygon.length];
      const dx = b[0] - a[0];
      const dy = b[1] - a[1];
      const length = Math.hypot(dx, dy) || 1;
      const near = onSegment(a, b, wantedX, wantedY);
      // A hair inside the edge, so the point counts as within the region.
      points.push([near[0] - (dy / length) * 0.002, near[1] + (dx / length) * 0.002]);
      cx += a[0];
      cy += a[1];
    }
    points.push([cx / polygon.length, cy / polygon.length]);
  }
  const step = Math.max(0.15, Math.max(box.max[0] - box.min[0], box.max[1] - box.min[1]) / 65);
  for (let x = box.min[0]; x <= box.max[0]; x += step) {
    for (let y = box.min[1]; y <= box.max[1]; y += step) points.push([x, y]);
  }

  let best = null;
  let nearest = Infinity;
  for (const [x, y] of points) {
    const distance = (x - wantedX) ** 2 + (y - wantedY) ** 2;
    if (distance < nearest && fits(x, y)) {
      best = { x, y };
      nearest = distance;
    }
  }
  if (!best) throw new Error("There's no room for that magnet. Use fewer or smaller ones, or make the keyring bigger.");
  return best;
}

// ---- finishing.js ----

// Rounded and bevelled edges.
//
// Extruding a flat outline gives square edges. A keyring wants the top edge of its letters and its border eased,
// and often the underside bevelled so it leaves the plate cleanly. Rather than build a rounded solid, the solid is
// extruded in slices and each slice is pulled towards the shape inset by the radius — so the edge follows a
// quarter circle, and every point lands where a true inset outline says it should rather than along a normal,
// which is what stops neighbouring curve segments rippling against each other.
//

/** How big each eased edge is, in mm: an explicit size when there is one, else the shared radius if it's on. */
export function edgeSizes(settings) {
  const size = (key, flag) =>
    Number.isFinite(settings[key])
      ? Math.max(0, Math.min(3, settings[key]))
      : settings[flag]
        ? Math.max(0.1, Math.min(3, +settings.roundRadius || 0.4))
        : 0;
  return {
    letter: size("letterTopSize", "letterRound"),
    border: size("borderTopSize", "borderRound"),
    bottom: size("bottomBevelSize", "borderBevel"),
  };
}

/** How many slices the quarter circle is cut into. Enough to read as round at any size a keyring is printed. */
const ROUND_STEPS = 16;

/**
 * A cross-section extruded to `height`, with its top and bottom edges eased by the sizes given.
 *
 * `keep` is the engine's bookkeeper: every Manifold object made here is handed to it so it can be freed.
 */
export function finishedExtrude(cs, height, { top = 0, bottom = 0, report = () => {}, component = false } = {}, keep) {
  // Separate pieces are eased one at a time: a radius that fits a wide piece can swallow a narrow one.
  if (!component && (top || bottom)) {
    const parts = cs.decompose().map(keep);
    if (parts.length > 1) {
      let combined;
      for (const part of parts) {
        const solid = finishedExtrude(part, height, { top, bottom, report, component: true }, keep);
        combined = combined ? keep(combined.add(solid)) : solid;
      }
      return combined;
    }
  }

  let radius = Math.min(Math.max(top, bottom), height * (top && bottom ? 0.45 : 0.9));
  if (!radius) {
    report({ top: 0, bottom: 0 });
    return keep(cs.extrude(height));
  }

  // The shape inset by the radius is where the eased edge has to land. A radius that would collapse a thin stroke
  // is backed off until the inset still has every piece and most of its area.
  const polygons = cs.toPolygons();
  const area = cs.area();
  const probe = (by) => {
    const inset = keep(cs.offset(-by, "Miter", 2, 96));
    const got = inset.toPolygons();
    return !inset.isEmpty() && got.length === polygons.length && inset.area() > area * 0.2 ? got : null;
  };
  let insetPolys = probe(radius);
  let usable = Boolean(insetPolys);
  if (!usable) {
    let low = 0;
    let high = radius;
    for (let attempt = 0; attempt < 10; attempt++) {
      const middle = (low + high) / 2;
      const got = probe(middle);
      if (got) {
        low = middle;
        insetPolys = got;
        usable = true;
      } else {
        high = middle;
      }
    }
    radius = low;
  }
  if (!usable || !insetPolys?.length || radius < 0.005) {
    report({ top: 0, bottom: 0 });
    return keep(cs.extrude(height));
  }

  const edgesOf = (polys) =>
    polys.flatMap((p) =>
      p.map((a, i) => {
        const b = p[(i + 1) % p.length];
        const dx = b[0] - a[0];
        const dy = b[1] - a[1];
        return { a, dx, dy, lengthSquared: dx * dx + dy * dy };
      }),
    );

  // Finding the nearest edge for every point of a long line of text is the slow part, so the edges go into square
  // buckets and only the buckets near the point are looked at.
  const all = polygons.flat();
  const xs = all.map((p) => p[0]);
  const ys = all.map((p) => p[1]);
  const cell = Math.max(
    radius * 2,
    (Math.max(...xs) - Math.min(...xs)) / 128,
    (Math.max(...ys) - Math.min(...ys)) / 128,
    0.25,
  );
  const index = (segments) => {
    const cells = new Map();
    for (const edge of segments) {
      const bx = edge.a[0] + edge.dx;
      const by = edge.a[1] + edge.dy;
      for (let x = Math.floor(Math.min(edge.a[0], bx) / cell); x <= Math.floor(Math.max(edge.a[0], bx) / cell); x++) {
        for (let y = Math.floor(Math.min(edge.a[1], by) / cell); y <= Math.floor(Math.max(edge.a[1], by) / cell); y++) {
          const key = `${x},${y}`;
          if (!cells.has(key)) cells.set(key, []);
          cells.get(key).push(edge);
        }
      }
    }
    return { segments, cells };
  };
  const boundary = index(edgesOf(polygons));
  const target = index(edgesOf(insetPolys));

  const nearest = (point, grid) => {
    let best = Infinity;
    let found;
    const gx = Math.floor(point[0] / cell);
    const gy = Math.floor(point[1] / cell);
    const seen = new Set();
    const check = (edge) => {
      if (seen.has(edge)) return;
      seen.add(edge);
      const along = edge.lengthSquared
        ? Math.max(
            0,
            Math.min(1, ((point[0] - edge.a[0]) * edge.dx + (point[1] - edge.a[1]) * edge.dy) / edge.lengthSquared),
          )
        : 0;
      const x = edge.a[0] + along * edge.dx;
      const y = edge.a[1] + along * edge.dy;
      const distance = (point[0] - x) ** 2 + (point[1] - y) ** 2;
      if (distance < best) {
        best = distance;
        found = [x, y];
      }
    };
    // Ring by ring outwards, stopping as soon as nothing outside could be nearer.
    for (let ring = 0; ring <= 4; ring++) {
      for (let x = gx - ring; x <= gx + ring; x++) {
        for (let y = gy - ring; y <= gy + ring; y++) {
          if (ring && x !== gx - ring && x !== gx + ring && y !== gy - ring && y !== gy + ring) continue;
          for (const edge of grid.cells.get(`${x},${y}`) || []) check(edge);
        }
      }
      const margin = Math.min(
        point[0] - (gx - ring) * cell,
        (gx + ring + 1) * cell - point[0],
        point[1] - (gy - ring) * cell,
        (gy + ring + 1) * cell - point[1],
      );
      if (best <= margin * margin + 1e-14) return { best, point: found };
    }
    for (const edge of grid.segments) check(edge);
    return { best, point: found };
  };

  // The slices are spent on the quarter circle, not on the straight wall between, and stepped by equal angle so
  // the last one meets the flat top tangentially instead of as a visible facet.
  const topRadius = Math.min(top, radius);
  const bottomRadius = Math.min(bottom, radius);
  const levels = [0];
  report({ top: topRadius, bottom: bottomRadius });
  if (bottomRadius) levels.push(bottomRadius);
  if (topRadius) {
    levels.push(height - topRadius);
    for (let i = 1; i <= ROUND_STEPS; i++) {
      levels.push(height - topRadius + topRadius * Math.sin(((i / ROUND_STEPS) * Math.PI) / 2));
    }
  } else {
    levels.push(height);
  }
  const heights = [...new Set(levels)].sort((a, b) => a - b);
  const body = keep(cs.extrude(height, heights.length - 2));
  const directions = new Map();

  return keep(
    body.warp((v) => {
      v[2] = heights[Math.max(0, Math.min(heights.length - 1, Math.round((v[2] / height) * (heights.length - 1))))];
      let shift = 0;
      if (topRadius && v[2] > height - topRadius) {
        shift = topRadius - Math.sqrt(Math.max(0, topRadius * topRadius - (v[2] - height + topRadius) ** 2));
      }
      if (bottomRadius && v[2] < bottomRadius) shift = Math.max(shift, bottomRadius - v[2]);
      if (shift < 1e-8) return;
      const key = `${v[0]},${v[1]}`;
      let delta = directions.get(key);
      if (!delta) {
        // Only points on the outer wall move; anything already inside stays where it is.
        const on = nearest(v, boundary);
        if (on.best > 1e-9) {
          directions.set(key, [0, 0]);
          return;
        }
        const to = nearest(v, target).point;
        delta = [to[0] - v[0], to[1] - v[1]];
        directions.set(key, delta);
      }
      v[0] += (delta[0] * shift) / radius;
      v[1] += (delta[1] * shift) / radius;
    }),
  );
}

// ---- meshNormals.js ----

// Normals for the preview.
//
// A solid that came out of a boolean is covered in triangles of wildly different sizes, and shading each by its
// own face leaves the walls striped. Averaging every triangle meeting at a point would instead round off the
// corners that ought to be sharp. So a point's normal is the average of the faces around it weighted by the angle
// each one turns through, and only of the faces within the crease angle — the flat top stays flat, the wall stays
// a wall, and the edge between them stays an edge.
//

export function creasedGeometry(vertices, triangles, creaseDegrees = 55) {
  const faces = triangles.length / 3;
  const faceNormals = new Float64Array(faces * 3);
  const atPoint = new Map();
  const corners = [];

  // Points that share coordinates share their normals, even where the solid lists them separately.
  for (let i = 0; i < vertices.length; i += 3) {
    const key = [vertices[i], vertices[i + 1], vertices[i + 2]].map((v) => v.toFixed(5)).join(",");
    if (!atPoint.has(key)) atPoint.set(key, []);
    corners.push(atPoint.get(key));
  }

  for (let face = 0; face < faces; face++) {
    const ids = [triangles[face * 3], triangles[face * 3 + 1], triangles[face * 3 + 2]];
    const a = ids[0] * 3;
    const b = ids[1] * 3;
    const c = ids[2] * 3;
    const ux = vertices[b] - vertices[a];
    const uy = vertices[b + 1] - vertices[a + 1];
    const uz = vertices[b + 2] - vertices[a + 2];
    const vx = vertices[c] - vertices[a];
    const vy = vertices[c + 1] - vertices[a + 1];
    const vz = vertices[c + 2] - vertices[a + 2];
    const normal = [uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx];
    const length = Math.hypot(...normal) || 1;
    for (let k = 0; k < 3; k++) faceNormals[face * 3 + k] = normal[k] / length;

    for (let corner = 0; corner < 3; corner++) {
      const i = ids[corner] * 3;
      const j = ids[(corner + 1) % 3] * 3;
      const k = ids[(corner + 2) % 3] * 3;
      const u = [0, 1, 2].map((d) => vertices[j + d] - vertices[i + d]);
      const v = [0, 1, 2].map((d) => vertices[k + d] - vertices[i + d]);
      const cross = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
      const angle = Math.atan2(
        Math.hypot(...cross),
        u.reduce((total, x, d) => total + x * v[d], 0),
      );
      corners[ids[corner]].push({ face, angle });
    }
  }

  const positions = new Float32Array(triangles.length * 3);
  const normals = new Float32Array(triangles.length * 3);
  const crease = Math.cos((creaseDegrees * Math.PI) / 180);
  for (let i = 0; i < triangles.length; i++) {
    const vertex = triangles[i];
    const face = Math.floor(i / 3);
    const sum = [0, 0, 0];
    for (const { face: other, angle } of corners[vertex]) {
      let facing = 0;
      for (let k = 0; k < 3; k++) facing += faceNormals[face * 3 + k] * faceNormals[other * 3 + k];
      if (facing + 1e-8 >= crease) for (let k = 0; k < 3; k++) sum[k] += faceNormals[other * 3 + k] * angle;
    }
    const length = Math.hypot(...sum) || 1;
    for (let k = 0; k < 3; k++) {
      positions[i * 3 + k] = vertices[vertex * 3 + k];
      normals[i * 3 + k] = sum[k] / length;
    }
  }
  return { positions, normals };
}

// ---- engine.js ----

// The keyring itself: text in, solids out.
//
// The shape of it: every character becomes its real outline from the font; the outlines are slid together until
// they touch and spaced by the gap asked for; each letter is grown outwards by the border width and the results
// unioned into one footprint; anything still in pieces is bridged; ring holes are placed where they will hold;
// then the footprint is extruded for the base and the border, the letters are extruded on top, and the letters
// are subtracted from the shell so the two fit each other exactly.
//
// All the two-dimensional work is Manifold's CrossSection — union, offset, hull, subtract — which is why a letter
// with a counter needs no special handling: its outline is a contour with a hole in it, and the hole survives
// every operation. The width is reached by solving for the scale rather than guessing, because the border, the
// gaps and the ring all add to it.
//


/** Everything the engine takes, and what it falls back to. Sizes are millimetres. */
export const DEFAULTS = {
  text: "Keyring",
  width: 60,
  widthLocked: true,
  textScale: null,
  align: "center",
  lineGap: 3,
  stroke: 0,
  infill: 0,
  fillVoids: false,
  smoothBorder: false,
  smoothRadius: 0.6,
  letterRound: false,
  borderRound: false,
  borderBevel: false,
  roundRadius: 0.4,
  letterTopSize: null,
  borderTopSize: null,
  bottomBevelSize: null,
  magnetRibs: false,
  magnetRibSize: 0.1,
  magnetEnabled: false,
  magnetMode: "open",
  magnetBase: null,
  magnetAutoHeight: true,
  magnetDiameterGap: 0.2,
  magnetDepthGap: 0.1,
  magnets: [],
  gap: 1.2,
  letterDepth: 3,
  borderDepth: 2,
  borderWidth: 1.4,
  base: 1,
  bridge: 2.4,
  clearance: 0.2,
  assembled: true,
  separate: false,
  holes: [{ x: -0.94, y: 0.2, inner: 4, outer: 8, localJoin: true, reinforce: true }],
};

/** Whether a solid came out without complaint. Manifold has reported this as a string and as an object with a
 *  value over its versions, so both are accepted rather than pinning the tool to one. */
const isSound = (solid) => {
  const status = solid.status();
  return status === "NoError" || status === 0 || status?.value === 0;
};

/** A space in the text moves the pen this far, in the font's own units before scaling. */
const SPACE_UNITS = 35;
/** Glyphs are read at this size and scaled afterwards, so the outline's detail doesn't depend on the final size. */
const GLYPH_SIZE = 100;

/**
 * Builds the keyring.
 *
 * `font` is an opentype font, `api` is Manifold's `{ CrossSection, Manifold }`, and `contours` turns a glyph's
 * path into polygons. Returns the solids to print, with their meshes, and everything the window needs to describe
 * what it made.
 */
/**
 * An error the window can put in the user's own language: it carries a code and whatever the sentence filled in,
 * while the message itself stays readable English for anything reading it plainly.
 */
function fail(code, message, vars) {
  const error = new Error(message);
  error.code = code;
  if (vars) error.vars = vars;
  return error;
}

export function buildModel(font, api, input, contours) {
  const s = { ...DEFAULTS, ...input };
  s.base = effectiveBase(s);
  s.text = normalizeText(s.text);

  if (!font) throw fail("noFont", "Load a font first.");
  if (!s.text.trim()) throw fail("noText", "Type something to put on the keyring.");
  const stats = textStats(s.text);
  if (stats.characters > MAX_CHARACTERS)
    throw fail("tooManyCharacters", `That's more than ${MAX_CHARACTERS} characters.`, { max: MAX_CHARACTERS });
  if (stats.lines > MAX_LINES) throw fail("tooManyLines", `That's more than ${MAX_LINES} lines.`, { max: MAX_LINES });
  if (!["left", "center", "right"].includes(s.align)) throw fail("badAlign", "Pick how the lines line up.");
  for (const key of [
    "width",
    "gap",
    "lineGap",
    "letterDepth",
    "borderDepth",
    "borderWidth",
    "base",
    "bridge",
    "clearance",
    "stroke",
    "infill",
    "smoothRadius",
  ]) {
    if (!Number.isFinite(s[key])) throw fail("notNumbers", "Every setting has to be a number.");
  }
  if (s.lineGap < 0) throw fail("negativeLineGap", "The space between lines can't be negative.");
  if (s.smoothBorder && s.smoothRadius <= 0)
    throw fail("badSmoothRadius", "The smoothing radius has to be more than nothing.");
  if (
    s.base <= 0 ||
    s.borderDepth <= 0 ||
    s.letterDepth <= 0 ||
    s.bridge <= 0 ||
    s.borderWidth <= 0 ||
    s.gap < 0 ||
    s.infill < 0
  ) {
    throw fail("nonPositive", "Heights and widths have to be more than nothing, and gaps can't be negative.");
  }
  if (s.width < 15) throw fail("tooNarrow", "Make it at least 15 mm across.", { min: 15 });
  const missing = [...new Set([...s.text].filter((c) => c.trim() && !font.charToGlyphIndex(c)))];
  if (missing.length)
    throw fail("missingGlyphs", `This font has no ${missing.join(" ")}. Try another font.`, {
      glyphs: missing.join(" "),
    });

  // Read every glyph once, at a fixed size. How finely the curves are cut follows the final scale, so a small
  // keyring doesn't carry a million points and a large one doesn't come out faceted.
  const advances = s.text.split("\n").map((line) => font.getAdvanceWidth(line, GLYPH_SIZE));
  const guessScale =
    !s.widthLocked && Number.isFinite(s.textScale) && s.textScale > 0
      ? s.textScale
      : s.width / Math.max(1, ...advances);
  const tolerance = Math.max(0.002, Math.min(0.12, 0.02 / guessScale));

  const glyphs = [];
  const rows = Array.from({ length: stats.lines }, () => []);
  let spaces = 0;
  let row = 0;
  for (const [i, character] of [...s.text].entries()) {
    if (character === "\n") {
      row++;
      spaces = 0;
      continue;
    }
    const polygons = contours(font.charToGlyph(character).getPath(0, 0, GLYPH_SIZE), tolerance);
    if (polygons.length) {
      const glyph = { i, ch: character, p: polygons, spaces, row };
      glyphs.push(glyph);
      rows[row].push(glyph);
      spaces = 0;
    } else {
      spaces++;
    }
  }
  if (!glyphs.length) throw fail("nothingToPrint", "There's nothing here to print.");

  const rawBounds = bounds(glyphs.flatMap((glyph) => glyph.p));
  const baseline = (rawBounds.min[1] + rawBounds.max[1]) / 2;
  const rawWidth = Math.max(
    ...rows.map((line) =>
      line.reduce((total, glyph) => {
        const box = bounds(glyph.p);
        return total + box.max[0] - box.min[0] + glyph.spaces * SPACE_UNITS;
      }, 0),
    ),
  );

  const { CrossSection: C, Manifold: M } = api;
  // Manifold hands back objects that have to be freed by hand; every one made here is noted and freed at the end.
  const rubbish = [];
  const keep = (x) => (rubbish.push(x), x);
  const union = (list) => keep(C.union(list));
  const subtract = (a, b) => keep(a.subtract(b));
  const add = (a, b) => keep(a.add(b));
  const move = (a, x, y) => keep(a.translate([x, y]));

  try {
    /** Lays the text out at a scale and returns the footprint it makes. */
    function layout(scale) {
      const lines = [];
      for (const line of rows) {
        const placed = [];
        const letters = [];
        let first = true;
        let furthest = -Infinity;
        for (const glyph of line) {
          let cs = keep(
            new C(
              glyph.p.map((p) => p.map(([x, y]) => [x * scale, (y - baseline) * scale])),
              "EvenOdd",
            ),
          );
          if (s.stroke) cs = keep(cs.offset(s.stroke, "Round", 2, 128));
          if (cs.isEmpty())
            throw fail("strokesTooThin", "The strokes are too thin and the letters vanish. Thicken them.");
          const polygons = cs.toPolygons();
          const own = bounds(polygons);

          // Slide this letter left until it touches one already placed, then back off by the gap. Only letters
          // whose heights overlap can touch, which is what keeps "AV" tight and "LT" apart.
          let touch = -Infinity;
          if (!first) {
            for (let i = placed.length - 1; i >= 0; i--) {
              const previous = placed[i];
              if (previous.max[0] - own.min[0] <= touch || previous.max[1] < own.min[1] || previous.min[1] > own.max[1])
                continue;
              touch = Math.max(touch, touchingShift(previous.p, polygons, false));
            }
          }
          if (!Number.isFinite(touch)) touch = furthest - own.min[0];
          const dx = first ? -own.min[0] : touch + s.gap + glyph.spaces * SPACE_UNITS * scale + 0.00002;
          first = false;
          cs = move(cs, dx, 0);
          const moved = shiftPolys(polygons, dx, 0);
          const box = bounds(moved);
          placed.push({ p: moved, ...box });
          furthest = Math.max(furthest, box.max[0]);
          letters.push({ ...glyph, cs, p: moved });
        }
        lines.push({ letters, box: letters.length ? bounds(letters.flatMap((g) => g.p)) : null });
      }

      const widest = Math.max(...lines.map((line) => (line.box ? line.box.max[0] - line.box.min[0] : 0)));
      const letters = [];
      const emptyHeight = Math.max((rawBounds.max[1] - rawBounds.min[1]) * scale + 2 * s.stroke, 0.01);
      let top = 0;
      for (const line of lines) {
        if (!line.box) {
          top -= emptyHeight + s.lineGap;
          continue;
        }
        const width = line.box.max[0] - line.box.min[0];
        const height = line.box.max[1] - line.box.min[1];
        const dx =
          -line.box.min[0] + (s.align === "left" ? 0 : s.align === "right" ? widest - width : (widest - width) / 2);
        const dy = top - line.box.max[1];
        for (const glyph of line.letters) {
          const cs = move(glyph.cs, dx, dy);
          const polygons = shiftPolys(glyph.p, dx, dy);
          // Only the outer contours are grown: growing a counter would close it.
          const outside = polygons.filter((p) => signedArea(p) > 0);
          const filled = keep(new C(outside, "Positive"));
          letters.push({ ...glyph, cs, p: polygons, outline: keep(filled.offset(s.borderWidth, "Round", 2, 128)) });
        }
        top -= height + s.lineGap + 0.00002;
      }

      let footprint = union(letters.map((glyph) => glyph.outline));

      // Letters too far apart to have merged leave the keyring in pieces; a bar between each pair joins them.
      const pieces = footprint.toPolygons().filter((p) => signedArea(p) > 0);
      const bars = [];
      for (const { p, q } of componentLinks(pieces)) {
        const dx = q[0] - p[0];
        const dy = q[1] - p[1];
        const length = Math.hypot(dx, dy);
        const bar = keep(C.square([length + s.bridge, s.bridge], true));
        const turned = keep(bar.rotate((Math.atan2(dy, dx) * 180) / Math.PI));
        bars.push(move(turned, (p[0] + q[0]) / 2, (p[1] + q[1]) / 2));
      }
      if (bars.length) footprint = union([footprint, ...bars]);

      let smoothingRadius = 0;
      if (s.smoothBorder) {
        // Round the real perimeter, bridge junctions included. The radius is capped against the border and bridge
        // widths so a thin band or a bar isn't rounded away.
        smoothingRadius = Math.min(s.smoothRadius, s.borderWidth * 0.45, s.bridge * 0.3);
        const r = smoothingRadius;
        const hull = keep(C.hull([footprint]));
        const grown = keep(footprint.offset(r, "Round", 2, 64));
        const closed = keep(grown.offset(-r, "Round", 2, 64));
        const inset = keep(closed.offset(-r, "Round", 2, 64));
        const rounded = keep(inset.offset(r, "Round", 2, 64));
        // Rounding can eat into a letter's own edge, so a thin skin of every letter is put back.
        const cover = union(
          letters.map((g) => keep(g.cs.offset(Math.min(s.borderWidth * 0.25, 0.35), "Round", 2, 128))),
        );
        footprint = union([keep(rounded.intersect(hull)), cover]);
      }

      // The ring is attached to the unfilled outline, so turning infill on never moves it.
      const attachment = footprint;
      if (s.infill > 0) {
        const hull = keep(C.hull([footprint]));
        const grown = keep(footprint.offset(s.infill, "Round", 2, 128));
        const closed = keep(grown.offset(-s.infill, "Round", 2, 128));
        footprint = add(footprint, keep(closed.intersect(hull)));
      }

      const outlinePolys = attachment.toPolygons();
      const box = bounds(outlinePolys);
      const cx = (box.min[0] + box.max[0]) / 2;
      const cy = (box.min[1] + box.max[1]) / 2;
      const halfWidth = (box.max[0] - box.min[0]) / 2;
      const halfHeight = (box.max[1] - box.min[1]) / 2;
      const letterUnion = union(letters.map((g) => g.cs));
      const letterPolys = letterUnion.toPolygons();
      const holePaths = [];
      const holeInfo = [];
      const ringDisks = [];

      for (const hole of s.holes) {
        if (
          ![hole.x, hole.y, hole.inner, hole.outer].every(Number.isFinite) ||
          hole.inner <= 0 ||
          hole.inner > hole.outer * 0.9 ||
          hole.outer <= 0
        ) {
          throw fail("ringTooBig", "A ring's hole has to be smaller than nine tenths of the ring.");
        }
        const safe = snapHole(
          outlinePolys,
          letterPolys,
          hole,
          cx + hole.x * halfWidth,
          cy + hole.y * halfHeight,
          s.borderWidth,
        );
        const outer = move(keep(C.circle(hole.outer / 2, 128)), safe.x, safe.y);
        const inner = move(keep(C.circle(hole.inner / 2, 128)), safe.x, safe.y);
        const overlap = keep((hole.localJoin ? inner : outer).intersect(letterUnion));
        if (overlap.area() > 1e-5) throw fail("ringHitsLetters", "That ring runs into the letters. Move it.");

        if (s.infill > 0) {
          // Keep the infill clear of the ring, so the ring still reads as a ring.
          const clear = move(keep(C.circle(hole.outer / 2 + 0.3, 64)), safe.x, safe.y);
          const infillOnly = subtract(footprint, attachment);
          footprint = union([attachment, subtract(infillOnly, clear), ...ringDisks]);
        }
        footprint = add(footprint, outer);

        if (hole.localJoin && hole.reinforce !== false) {
          // A hull between the ring and the body right behind it gives tangent shoulders, instead of the ring
          // meeting the body at a corner that would snap.
          const n = safe.normal;
          const t = [-n[1], n[0]];
          const w = hole.outer * 0.6;
          const d = hole.outer * 0.55;
          const a = safe.anchor;
          const clip = keep(
            new C(
              [
                [
                  [a[0] + t[0] * w + n[0] * 0.15, a[1] + t[1] * w + n[1] * 0.15],
                  [a[0] - t[0] * w + n[0] * 0.15, a[1] - t[1] * w + n[1] * 0.15],
                  [a[0] - t[0] * w - n[0] * d, a[1] - t[1] * w - n[1] * d],
                  [a[0] + t[0] * w - n[0] * d, a[1] + t[1] * w - n[1] * d],
                ],
              ],
              "EvenOdd",
            ),
          );
          const nearby = keep(attachment.intersect(clip));
          if (!nearby.isEmpty()) footprint = add(footprint, keep(C.hull([outer, nearby])));
          const fillet = Math.min(0.65, s.borderWidth * 0.4, (hole.outer - hole.inner) * 0.2);
          const zone = move(keep(C.circle(hole.outer * 0.95, 96)), safe.x, safe.y);
          if (fillet > 0.03) {
            const grown = keep(footprint.offset(fillet, "Round", 2, 96));
            const closed = keep(grown.offset(-fillet, "Round", 2, 96));
            footprint = add(footprint, keep(closed.intersect(zone)));
          }
        }
        ringDisks.push(outer);
        holePaths.push(inner);
        holeInfo.push({ ...hole, ...safe });
      }

      // Dropping every negative contour fills the counters, whatever made them. It happens before the ring holes
      // are cut, so those survive.
      let filledVoidArea = 0;
      if (s.fillVoids) {
        const filled = keep(
          new C(
            footprint.toPolygons().filter((p) => signedArea(p) > 0),
            "Positive",
          ),
        );
        filledVoidArea = Math.max(0, filled.area() - footprint.area());
        footprint = filled;
      }
      const internalHoleCount = footprint.toPolygons().filter((p) => signedArea(p) < 0).length;
      const cut = holePaths.length ? union(holePaths) : null;
      if (cut) footprint = subtract(footprint, cut);

      const whole = bounds(footprint.toPolygons());
      return {
        letters,
        footprint,
        letterUnion,
        cut,
        outlinePolys,
        letterPolys,
        frame: { min: box.min, max: box.max },
        holeInfo,
        width: whole.max[0] - whole.min[0],
        smoothingRadius,
        filledVoidArea,
        internalHoleCount,
      };
    }

    // Solve for the scale that makes the finished width the one asked for. The width isn't proportional to the
    // scale — the border, the gaps and the ring don't grow with the text — so it's solved by secant steps,
    // bracketed so it can't wander.
    let scale =
      Number.isFinite(s.textScale) && s.textScale > 0
        ? s.textScale
        : Math.max(
            0.01,
            (s.width -
              2 * s.borderWidth -
              s.gap * (Math.max(...rows.map((line) => line.length)) - 1) -
              (s.holes[0]?.outer || 0)) /
              rawWidth,
          );
    const fitWidth = s.widthLocked || !Number.isFinite(s.textScale) || s.textScale <= 0;
    let laid;
    let previous = null;
    let low = 0;
    let high = Infinity;
    for (let attempt = 0; attempt < (fitWidth ? 14 : 1); attempt++) {
      laid = layout(scale);
      if (!fitWidth || Math.abs(laid.width - s.width) < 0.025) break;
      if (laid.width > s.width) high = scale;
      else low = scale;
      const slope = previous ? (laid.width - previous.width) / (scale - previous.scale) : rawWidth;
      let next = scale + (s.width - laid.width) / Math.max(slope, 1);
      if (!Number.isFinite(next) || next <= low || next >= high)
        next = Number.isFinite(high) ? (low + high) / 2 : scale * 1.5;
      previous = { scale, width: laid.width };
      scale = Math.max(0.0001, next);
    }
    if (fitWidth && Math.abs(laid.width - s.width) > 0.08) {
      throw fail(
        "wontFitWidth",
        "That won't fit the width you set. Narrow the gaps, the border or the ring, or make it wider.",
      );
    }

    const { letters, footprint, letterUnion, holeInfo } = laid;
    const models = [];
    const wantedEdges = edgeSizes(s);
    const appliedEdges = Object.fromEntries(
      Object.entries(wantedEdges).map(([key, requested]) => [key, { requested, min: Infinity, max: 0 }]),
    );
    const track = (key, value) => {
      appliedEdges[key].min = Math.min(appliedEdges[key].min, value);
      appliedEdges[key].max = Math.max(appliedEdges[key].max, value);
    };

    // Every letter is its own solid, standing on the base, so each can take its own colour.
    const bodies = letters.map((glyph) => {
      const body = finishedExtrude(
        glyph.cs,
        s.letterDepth,
        { top: wantedEdges.letter, report: (r) => track("letter", r.top) },
        keep,
      );
      const raised = keep(body.translate([0, 0, s.base]));
      models.push({
        name: `letter_${glyph.i + 1}`,
        index: glyph.i,
        char: glyph.ch,
        row: glyph.row,
        kind: "letter",
        solid: raised,
      });
      return raised;
    });

    // Printing the pieces apart needs the hole in the border to be bigger than the letter by the fit clearance.
    const cavity = s.separate && s.clearance > 0 ? keep(letterUnion.offset(s.clearance, "Round", 2, 128)) : letterUnion;
    const upper = subtract(footprint, cavity);
    const base = finishedExtrude(
      footprint,
      s.base,
      { bottom: wantedEdges.bottom, report: (r) => track("bottom", r.bottom) },
      keep,
    );
    const border = finishedExtrude(
      upper,
      s.borderDepth,
      { top: wantedEdges.border, report: (r) => track("border", r.top) },
      keep,
    );
    let shell = keep(base.add(keep(border.translate([0, 0, s.base]))));
    shell = keep(shell.subtract(keep(M.union(bodies))));

    const magnets = [];
    const magnetRegions = [];
    if (s.magnetEnabled) {
      for (const magnet of normalizeMagnets(s)) {
        const radius = (magnet.diameter + (+s.magnetDiameterGap || 0)) / 2;
        const region = keep(footprint.offset(-radius - 0.6 - appliedEdges.bottom.max, "Round", 2, 128));
        const polygons = region.toPolygons();
        if (!polygons.length) throw fail("noRoomForMagnet", "There's no room for a magnet. Make the keyring bigger.");
        const frame = laid.frame;
        const cx = (frame.min[0] + frame.max[0]) / 2;
        const cy = (frame.min[1] + frame.max[1]) / 2;
        const halfWidth = (frame.max[0] - frame.min[0]) / 2;
        const halfHeight = (frame.max[1] - frame.min[1]) / 2;
        const safe = snapInRegion(polygons, cx + magnet.x * halfWidth, cy + magnet.y * halfHeight, magnets, radius);
        const depth = magnet.depth + (+s.magnetDepthGap || 0);
        const z = s.magnetMode === "embedded" ? 0.4 : -0.01;
        const pocket = keep(move(keep(C.circle(radius, 64)), safe.x, safe.y).extrude(depth + (z < 0 ? 0.01 : 0)));
        shell = keep(shell.subtract(keep(pocket.translate([0, 0, z]))));

        // Four short ribs grip the magnet. The circle they leave is never smaller than the magnet itself, and the
        // mouth is tapered so it still goes in.
        const ribSize =
          s.magnetRibs && s.magnetMode !== "embedded"
            ? Math.max(0, Math.min(+s.magnetRibSize || 0, radius - magnet.diameter / 2))
            : 0;
        if (ribSize > 1e-5) {
          const inner = radius - ribSize;
          const outer = radius + 0.25;
          const width = Math.max(0.45, Math.min(0.8, magnet.diameter * 0.12));
          const ramp = Math.min(0.4, depth * 0.45);
          const piece = move(keep(C.square([outer - inner, width], true)), (outer + inner) / 2, 0);
          const raw = keep(piece.extrude(depth, 3));
          const tapered = keep(
            raw.warp((v) => {
              if (Math.abs(v[0] - inner) < 1e-5 && v[2] < ramp) v[0] += ribSize * (1 - v[2] / ramp);
            }),
          );
          for (let angle = 0; angle < 360; angle += 90) {
            shell = keep(shell.add(keep(keep(tapered.rotate([0, 0, angle])).translate([safe.x, safe.y, 0]))));
          }
        }
        magnets.push({
          ...magnet,
          ...safe,
          radius,
          depth,
          ribSize,
          ribCount: ribSize > 1e-5 ? 4 : 0,
          gripDiameter: 2 * (radius - ribSize),
          normalizedX: (safe.x - cx) / halfWidth,
          normalizedY: (safe.y - cy) / halfHeight,
          pauseZ: s.magnetMode === "embedded" ? z + depth : null,
        });
        magnetRegions.push(polygons);
      }
    }

    // Offset curves that land on each other can leave specks of a billionth of a cubic millimetre. Those go; a
    // real piece that happens to be separate stays, and is reported instead.
    const parts = shell.decompose().map(keep);
    const real = parts.filter((part) => part.volume() > 1e-6);
    const count = real.length;
    if (!count)
      throw fail("borderNotSolid", "The border didn't come out as a solid. Try a wider border or a taller one.");
    const removedNumericalFragments = parts.length - count;
    if (removedNumericalFragments) shell = keep(M.union(real));
    models.push({ name: "border_and_base", kind: "border", solid: shell });

    // Everything is moved so the keyring sits over the middle, which is where a slicer expects it.
    const box = shell.boundingBox();
    const centre = [(box.min[0] + box.max[0]) / 2, (box.min[1] + box.max[1]) / 2, 0];
    const result = models.map((model) => {
      const mesh = model.solid.getMesh();
      const vertices = [];
      for (let i = 0; i < mesh.vertProperties.length; i += mesh.numProp) {
        vertices.push(
          mesh.vertProperties[i] - centre[0],
          mesh.vertProperties[i + 1] - centre[1],
          mesh.vertProperties[i + 2],
        );
      }
      if (!isSound(model.solid))
        throw fail("notClosed", "That didn't come out as a closed solid. Change a setting and try again.");
      return {
        name: model.name,
        index: model.index,
        char: model.char,
        row: model.row,
        kind: model.kind,
        vertices: new Float32Array(vertices),
        triangles: new Uint32Array(mesh.triVerts),
        volume: model.solid.volume(),
        // How many holes run through this piece, which is how a counter proves it survived: o is 1, B is 2, l is
        // 0. Below zero means the piece is in more than one lump, like the dot and the stem of an i.
        genus: model.solid.genus(),
      };
    });

    const min = [Infinity, Infinity, Infinity];
    const max = [-Infinity, -Infinity, -Infinity];
    for (const model of result) {
      for (let i = 0; i < model.vertices.length; i += 3) {
        for (let k = 0; k < 3; k++) {
          min[k] = Math.min(min[k], model.vertices[i + k]);
          max[k] = Math.max(max[k], model.vertices[i + k]);
        }
      }
    }

    const warnings = [];
    if (count > 1) warnings.push(`The border is in ${count} separate pieces. Widen the join, or fill the inside.`);
    if (s.borderDepth > s.letterDepth)
      warnings.push("The border stands higher than the letters. Look at it from the side.");
    if (s.bridge < 1.6) warnings.push("The join between letters is under 1.6 mm. It may be fragile.");
    if (s.holes.some((hole) => (hole.outer - hole.inner) / 2 < 0.8 - 1e-6)) {
      warnings.push("A ring's wall is under 0.8 mm. Make the hole smaller, or the ring bigger.");
    }

    const shift = (polygons) => shiftPolys(polygons, -centre[0], -centre[1]);
    return {
      models: result,
      effectiveBase: s.base,
      magnets: magnets.map((magnet) => ({ ...magnet, x: magnet.x - centre[0], y: magnet.y - centre[1] })),
      magnetRegions: magnetRegions.map(shift),
      textLayout: { lines: stats.lines, characters: stats.characters, align: s.align, lineGap: s.lineGap },
      size: max.map((value, i) => value - min[i]),
      textScale: scale,
      centre,
      bounds: { min, max },
      holes: holeInfo.map((hole) => ({
        ...hole,
        x: hole.x - centre[0],
        y: hole.y - centre[1],
        anchor: [hole.anchor[0] - centre[0], hole.anchor[1] - centre[1]],
      })),
      placement: {
        outlines: shift(laid.outlinePolys),
        letters: shift(laid.letterPolys),
        min: laid.frame.min.map((value, i) => value - centre[i]),
        max: laid.frame.max.map((value, i) => value - centre[i]),
      },
      finishing: {
        edges: Object.fromEntries(
          Object.entries(appliedEdges).map(([key, value]) => [
            key,
            { ...value, min: Number.isFinite(value.min) ? value.min : 0 },
          ]),
        ),
        removedNumericalFragments,
        smoothingRadius: laid.smoothingRadius,
        filledVoidArea: laid.filledVoidArea,
        internalHoleCount: laid.internalHoleCount,
      },
      warnings,
      connected: count === 1,
      triangles: result.reduce((total, model) => total + model.triangles.length / 3, 0),
    };
  } finally {
    for (const object of new Set(rubbish.reverse())) {
      try {
        object.delete();
      } catch {
        // Already freed, or never allocated: either way there is nothing to do.
      }
    }
  }
}

// ---- files.js ----

// The keyring as files.
//
// The 3MF keeps every piece as its own object inside one assembly, with the colours as a material list and a
// Bambu-style settings part naming the extruder for each — so a slicer opens it with the letters and the border
// already told apart and assigned, rather than as one lump to sort out by hand. No printer profile and no G-code
// go in: those belong to the person slicing it.
//


const utf8 = new TextEncoder();

let crcTable = null;
function crc32(bytes) {
  if (!crcTable) {
    crcTable = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) crc = crcTable[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

const deflate = async (bytes) => {
  const stream = new Blob([bytes]).stream().pipeThrough(new CompressionStream("deflate-raw"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
};

/** A ZIP of the entries given, each squeezed where squeezing helps. */
async function zip(entries) {
  const chunks = [];
  const directory = [];
  let offset = 0;
  for (const [name, text] of entries) {
    const nameBytes = utf8.encode(name);
    const raw = utf8.encode(text);
    const crc = crc32(raw);
    const packed = await deflate(raw);
    const squeezed = packed.length < raw.length;
    const data = squeezed ? packed : raw;

    const local = new Uint8Array(30);
    const view = new DataView(local.buffer);
    view.setUint32(0, 0x04034b50, true);
    view.setUint16(4, 20, true);
    view.setUint16(8, squeezed ? 8 : 0, true);
    view.setUint32(14, crc, true);
    view.setUint32(18, data.length, true);
    view.setUint32(22, raw.length, true);
    view.setUint16(26, nameBytes.length, true);
    chunks.push(local, nameBytes, data);

    const central = new Uint8Array(46);
    const centralView = new DataView(central.buffer);
    centralView.setUint32(0, 0x02014b50, true);
    centralView.setUint16(4, 20, true);
    centralView.setUint16(6, 20, true);
    centralView.setUint16(10, squeezed ? 8 : 0, true);
    centralView.setUint32(16, crc, true);
    centralView.setUint32(20, data.length, true);
    centralView.setUint32(24, raw.length, true);
    centralView.setUint16(28, nameBytes.length, true);
    centralView.setUint32(42, offset, true);
    directory.push(central, nameBytes);
    offset += local.length + nameBytes.length + data.length;
  }
  const directorySize = directory.reduce((total, part) => total + part.length, 0);
  const end = new Uint8Array(22);
  const endView = new DataView(end.buffer);
  endView.setUint32(0, 0x06054b50, true);
  endView.setUint16(8, entries.length, true);
  endView.setUint16(10, entries.length, true);
  endView.setUint32(12, directorySize, true);
  endView.setUint32(16, offset, true);

  const all = [...chunks, ...directory, end];
  const out = new Uint8Array(all.reduce((total, part) => total + part.length, 0));
  let at = 0;
  for (const part of all) {
    out.set(part, at);
    at += part.length;
  }
  return out;
}

const xml = (value) =>
  String(value).replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" })[c],
  );

/** How far apart pieces are laid out when they're to be printed separately, in mm. */
const APART = 5;

/** Where each piece sits: in place as it was built, or spread along x so nothing overlaps. */
function placement(models, separate) {
  let cursor = 0;
  return models.map((model) => {
    let minX = Infinity;
    let maxX = -Infinity;
    let minZ = Infinity;
    for (let i = 0; i < model.vertices.length; i += 3) {
      minX = Math.min(minX, model.vertices[i]);
      maxX = Math.max(maxX, model.vertices[i]);
      minZ = Math.min(minZ, model.vertices[i + 2]);
    }
    const dx = separate ? cursor - minX : 0;
    const dz = separate ? -minZ : 0;
    cursor += maxX - minX + APART;
    return { dx, dz };
  });
}

/** The keyring as a 3MF: one assembly, a part per piece, each with its colour and its extruder. */
export async function threeMf(models, colours, { separate = false, title = "Keyring" } = {}) {
  const issues = colourIssues(models.map((m) => m.char || "").join(""), colours, models);
  if (issues.duplicates.length) throw new Error(`${issues.duplicates.join(", ")} is given two colours at once.`);

  // Only the filaments actually in use: an extra colour switched off shouldn't make a slicer ask for a fourth
  // spool. The slots keep their numbers, so what is listed is everything up to the highest one used.
  const highest = models.reduce((top, model) => Math.max(top, colourSlot(model, colours)), 0);
  const colourList = palette(colours).slice(0, highest + 1);
  const identity = "1 0 0 0 1 0 0 0 1 0 0 0";
  const where = placement(models, separate);
  const assembly = 100;

  const parts = models.map((model, i) => {
    const { dx, dz } = where[i];
    const slot = colourSlot(model, colours);
    const name = `${model.name}${model.char ? ` ${model.char}` : ""} [${slot + 1}]`;
    let vertices = "";
    let triangles = "";
    for (let j = 0; j < model.vertices.length; j += 3) {
      vertices += `<vertex x="${(model.vertices[j] + dx).toFixed(6)}" y="${model.vertices[j + 1].toFixed(6)}" z="${(model.vertices[j + 2] + dz).toFixed(6)}"/>`;
    }
    for (let j = 0; j < model.triangles.length; j += 3) {
      triangles += `<triangle v1="${model.triangles[j]}" v2="${model.triangles[j + 1]}" v3="${model.triangles[j + 2]}"/>`;
    }
    return {
      id: i + 1,
      slot,
      name,
      mesh:
        `<object id="${i + 1}" type="model" name="${xml(name)}" pid="${1000 + slot}" pindex="0">` +
        `<mesh><vertices>${vertices}</vertices><triangles>${triangles}</triangles></mesh></object>`,
    };
  });

  const groups = colourList
    .map((colour, i) => `<m:colorgroup id="${1000 + i}"><m:color color="${colour.toUpperCase()}FF"/></m:colorgroup>`)
    .join("");
  const model =
    `<?xml version="1.0" encoding="UTF-8"?>` +
    `<model unit="millimeter" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02" ` +
    `xmlns:m="http://schemas.microsoft.com/3dmanufacturing/material/2015/02">` +
    `<metadata name="Title">${xml(title)}</metadata>` +
    `<metadata name="Application">Thingport keyring generator</metadata>` +
    `<resources>${groups}${parts.map((p) => p.mesh).join("")}` +
    `<object id="${assembly}" type="model" name="${xml(title)}"><components>` +
    parts.map((p) => `<component objectid="${p.id}" transform="${identity}"/>`).join("") +
    `</components></object></resources>` +
    `<build><item objectid="${assembly}" transform="${identity}"/></build></model>`;

  const settings =
    `<?xml version="1.0" encoding="UTF-8"?><config><object id="${assembly}">` +
    `<metadata key="name" value="${xml(title)}"/><metadata key="extruder" value="1"/>` +
    parts
      .map(
        (p) =>
          `<part id="${p.id}" subtype="normal_part"><metadata key="name" value="${xml(p.name)}"/>` +
          `<metadata key="extruder" value="${p.slot + 1}"/></part>`,
      )
      .join("") +
    `</object></config>`;

  return zip([
    [
      "[Content_Types].xml",
      `<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">` +
        `<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>` +
        `<Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/>` +
        `<Default Extension="config" ContentType="application/xml"/>` +
        `<Default Extension="json" ContentType="application/json"/></Types>`,
    ],
    [
      "_rels/.rels",
      `<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">` +
        `<Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/></Relationships>`,
    ],
    ["3D/3dmodel.model", model],
    ["Metadata/model_settings.config", settings],
    [
      "Metadata/keyring-colours.json",
      JSON.stringify({
        slots: colourList.map((colour, i) => ({ slot: i + 1, colour })),
        parts: parts.map((p) => ({ name: p.name, slot: p.slot + 1 })),
      }),
    ],
  ]);
}

/** The keyring as an OBJ, one named object per piece. */
export function obj(models, { separate = false, title = "Keyring" } = {}) {
  const where = placement(models, separate);
  let offset = 1;
  let out = `# ${title}\n# Thingport keyring generator. Millimetres, Z up.\n`;
  models.forEach((model, i) => {
    const { dx, dz } = where[i];
    out += `o ${model.name}\n`;
    for (let j = 0; j < model.vertices.length; j += 3) {
      out += `v ${(model.vertices[j] + dx).toFixed(5)} ${model.vertices[j + 1].toFixed(5)} ${(model.vertices[j + 2] + dz).toFixed(5)}\n`;
    }
    for (let j = 0; j < model.triangles.length; j += 3) {
      out += `f ${model.triangles[j] + offset} ${model.triangles[j + 1] + offset} ${model.triangles[j + 2] + offset}\n`;
    }
    offset += model.vertices.length / 3;
  });
  return out;
}

/** Every piece in one binary STL, for anything that reads nothing else. STL carries no colours. */
export function stl(models, { separate = false, title = "Keyring" } = {}) {
  const where = placement(models, separate);
  const count = models.reduce((total, model) => total + model.triangles.length / 3, 0);
  const bytes = new Uint8Array(84 + count * 50);
  const view = new DataView(bytes.buffer);
  utf8.encodeInto(`${title} - Thingport keyring generator`.slice(0, 79), bytes.subarray(0, 80));
  view.setUint32(80, count, true);
  let at = 84;
  models.forEach((model, i) => {
    const { dx, dz } = where[i];
    const point = (index) => [
      model.vertices[index * 3] + dx,
      model.vertices[index * 3 + 1],
      model.vertices[index * 3 + 2] + dz,
    ];
    for (let j = 0; j < model.triangles.length; j += 3) {
      const a = point(model.triangles[j]);
      const b = point(model.triangles[j + 1]);
      const c = point(model.triangles[j + 2]);
      const ux = b[0] - a[0];
      const uy = b[1] - a[1];
      const uz = b[2] - a[2];
      const vx = c[0] - a[0];
      const vy = c[1] - a[1];
      const vz = c[2] - a[2];
      let nx = uy * vz - uz * vy;
      let ny = uz * vx - ux * vz;
      let nz = ux * vy - uy * vx;
      const length = Math.hypot(nx, ny, nz) || 1;
      nx /= length;
      ny /= length;
      nz /= length;
      for (const value of [nx, ny, nz, ...a, ...b, ...c]) {
        view.setFloat32(at, value, true);
        at += 4;
      }
      at += 2;
    }
  });
  return bytes;
}

// ---- viewer.js ----

// The keyring in three dimensions, drawn with Thingport's own Three.js.
//
// Each piece is its own mesh in its own colour, so a two-colour design looks here the way it will come off the
// printer, and a click can tell the letters from the border. Normals are welded only across shallow angles, so a
// rounded top looks rounded while the edge of the border stays an edge.
//
// It draws when something changes rather than every frame, so a still window costs nothing.


/** Where the camera starts, and the views the buttons jump to: around, up, and how close. */
const HOME = { around: -32, up: 34, zoom: 1 };
export const VIEWS = {
  home: HOME,
  front: { around: -90, up: 0, zoom: 1.08 },
  top: { around: -90, up: 89.9, zoom: 1.08 },
  side: { around: 0, up: 0, zoom: 1.08 },
};

/** Things of a known size to sit the keyring beside, so its size means something. Millimetres. */
export const SIZE_GUIDES = {
  none: null,
  card: { label: "Bank card", width: 85.6, height: 54 },
  phone: { label: "Phone", width: 71.5, height: 149.6 },
};

/**
 * A viewer on one canvas. `three` is what `library("three")` gives. Returns null where the browser has no WebGL,
 * and the window then shows the figures without a picture.
 */
export function createViewer(three, canvas, { onPick, onDrag } = {}) {
  let renderer;
  try {
    renderer = new three.WebGLRenderer({ canvas, antialias: true, alpha: true });
  } catch {
    return null;
  }
  renderer.setClearColor(0x000000, 0);

  const scene = new three.Scene();
  const camera = new three.PerspectiveCamera(36, 1, 0.1, 5000);
  // Lit from the front and above, with a soft fill, so a flat keyring still reads as a solid.
  const key = new three.DirectionalLight(0xffffff, 2.2);
  key.position.set(-0.4, -0.9, 1.1);
  const rim = new three.DirectionalLight(0xffffff, 0.7);
  rim.position.set(0.8, 0.6, 0.4);
  scene.add(key, rim, new three.AmbientLight(0xffffff, 1.1), new three.HemisphereLight(0xffffff, 0x404458, 1.2));

  const group = new three.Group();
  const guideGroup = new three.Group();
  const handleGroup = new three.Group();
  scene.add(group, guideGroup, handleGroup);

  const orbit = { ...HOME };
  const centre = new three.Vector3();
  let radius = 20;
  let frame = 0;
  let disposed = false;
  let selected = null;
  let handles = [];
  let dragging = null;

  function place() {
    // Far enough back that the whole thing fits whichever way the window is shaped: a long keyring in a tall
    // window is held by the narrower of the two angles the camera sees, not by a fixed multiple of its size.
    const upright = (camera.fov * Math.PI) / 180;
    const across = 2 * Math.atan(Math.tan(upright / 2) * Math.max(0.2, camera.aspect));
    const distance = (radius * 1.06) / Math.sin(Math.min(upright, across) / 2) / Math.max(0.15, orbit.zoom);
    const around = (orbit.around * Math.PI) / 180;
    const up = (orbit.up * Math.PI) / 180;
    camera.position.set(
      centre.x + distance * Math.cos(up) * Math.cos(around),
      centre.y + distance * Math.cos(up) * Math.sin(around),
      centre.z + distance * Math.sin(up),
    );
    camera.up.set(0, 0, 1);
    camera.lookAt(centre);
    camera.near = Math.max(0.1, distance - radius * 4);
    camera.far = distance + radius * 6;
    camera.updateProjectionMatrix();
  }

  function draw() {
    const ratio = Math.min(devicePixelRatio || 1, 2);
    const width = Math.max(1, canvas.clientWidth);
    const height = Math.max(1, canvas.clientHeight);
    renderer.setPixelRatio(ratio);
    if (
      renderer.domElement.width !== Math.round(width * ratio) ||
      renderer.domElement.height !== Math.round(height * ratio)
    ) {
      renderer.setSize(width, height, false);
    }
    camera.aspect = width / height;
    place();
    renderer.render(scene, camera);
  }

  const redraw = () => {
    if (frame || disposed) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      draw();
    });
  };
  const turn = (around, up) => {
    orbit.around = (orbit.around + around) % 360;
    orbit.up = Math.max(-89.9, Math.min(89.9, orbit.up + up));
    redraw();
  };
  const zoom = (factor) => {
    orbit.zoom = Math.max(0.15, Math.min(10, orbit.zoom * factor));
    redraw();
  };
  const look = (name) => {
    Object.assign(orbit, VIEWS[name] ?? HOME);
    redraw();
  };

  const raycaster = new three.Raycaster();
  const pointer = new three.Vector2();
  const at = (event) => {
    const box = canvas.getBoundingClientRect();
    pointer.set(((event.clientX - box.left) / box.width) * 2 - 1, -((event.clientY - box.top) / box.height) * 2 + 1);
    raycaster.setFromCamera(pointer, camera);
    return raycaster;
  };

  /** Where the pointer meets the plane the handles live on, in model millimetres. */
  const onPlane = (event, z) => {
    const ray = at(event).ray;
    const plane = new three.Plane(new three.Vector3(0, 0, 1), -z);
    const hit = ray.intersectPlane(plane, new three.Vector3());
    return hit ? { x: hit.x, y: hit.y } : null;
  };

  let last = null;
  const down = (event) => {
    if (event.button !== 0) return;
    place();
    if (handles.length) {
      const hit = at(event).intersectObjects(handleGroup.children, false)[0];
      if (hit) {
        const handle = handles.find((h) => h.mesh === hit.object);
        if (handle) {
          dragging = { handle, z: handle.z };
          canvas.setPointerCapture(event.pointerId);
          canvas.style.cursor = "grabbing";
          onPick?.(handle.pick);
          return;
        }
      }
    }
    const part = at(event).intersectObjects(group.children, false)[0];
    if (part) onPick?.(part.object.userData.pick ?? null);
    else onPick?.(null);
    canvas.setPointerCapture(event.pointerId);
    last = { x: event.clientX, y: event.clientY };
    canvas.style.cursor = "grabbing";
  };
  const move = (event) => {
    if (dragging) {
      const point = onPlane(event, dragging.z);
      if (point) {
        dragging.handle.mesh.position.set(point.x, point.y, dragging.z);
        onDrag?.(dragging.handle.pick, point);
        redraw();
      }
      return;
    }
    if (!last) return;
    turn(-(event.clientX - last.x) * 0.5, (event.clientY - last.y) * 0.4);
    last = { x: event.clientX, y: event.clientY };
  };
  const up = () => {
    if (dragging) onDrag?.(dragging.handle.pick, null, true);
    dragging = null;
    last = null;
    canvas.style.cursor = "";
  };
  const wheel = (event) => {
    event.preventDefault();
    zoom(event.deltaY > 0 ? 1 / 1.12 : 1.12);
  };
  const keys = (event) => {
    const steps = { ArrowLeft: [10, 0], ArrowRight: [-10, 0], ArrowUp: [0, -8], ArrowDown: [0, 8] };
    if (steps[event.key]) turn(...steps[event.key]);
    else if (event.key === "+" || event.key === "=") zoom(1.12);
    else if (event.key === "-" || event.key === "_") zoom(1 / 1.12);
    else if (event.key === "0" || event.key === "Home") look("home");
    else return;
    event.preventDefault();
  };
  const listeners = [
    ["pointerdown", down],
    ["pointermove", move],
    ["pointerup", up],
    ["pointercancel", up],
    ["keydown", keys],
  ];
  for (const [type, fn] of listeners) canvas.addEventListener(type, fn);
  canvas.addEventListener("wheel", wheel, { passive: false });
  const resize = new ResizeObserver(redraw);
  resize.observe(canvas);

  const empty = (host) => {
    for (const child of [...host.children]) {
      host.remove(child);
      child.geometry?.dispose?.();
      child.material?.dispose?.();
    }
  };

  /** One solid as geometry to draw: corner positions with the crease-aware normals, no index. */
  const build = (model) => {
    const { positions, normals } = creasedGeometry(model.vertices, model.triangles);
    const geometry = new three.BufferGeometry();
    geometry.setAttribute("position", new three.BufferAttribute(positions, 3));
    geometry.setAttribute("normal", new three.BufferAttribute(normals, 3));
    return geometry;
  };

  const shade = (colour, { selected: isSelected = false, hidden = false } = {}) =>
    new three.MeshStandardMaterial({
      color: new three.Color(colour),
      roughness: 0.6,
      metalness: 0.02,
      transparent: hidden,
      opacity: hidden ? 0.12 : 1,
      depthWrite: !hidden,
      emissive: new three.Color(isSelected ? 0x2a6bff : 0x000000),
      emissiveIntensity: isSelected ? 0.3 : 0,
    });

  return {
    /**
     * Shows the engine's solids. `colourOf` gives each one its colour, `hiddenOf` says which to ghost, and
     * `fit` recentres the camera — left off while someone is only nudging a ring about.
     */
    show(models, { colourOf, hiddenOf, fit = true } = {}) {
      empty(group);
      const box = new three.Box3();
      models.forEach((model, index) => {
        const geometry = build(model);
        const pick = { index, name: model.name, kind: model.kind, char: model.char };
        const mesh = new three.Mesh(
          geometry,
          shade(colourOf?.(model, index) ?? "#b9c2cf", {
            selected: selected === index,
            hidden: hiddenOf?.(model, index) ?? false,
          }),
        );
        mesh.userData.pick = pick;
        mesh.renderOrder = hiddenOf?.(model, index) ? 1 : 0;
        group.add(mesh);
        geometry.computeBoundingBox();
        if (!hiddenOf?.(model, index)) box.union(geometry.boundingBox);
      });
      if (box.isEmpty()) group.children.forEach((m) => box.union(m.geometry.boundingBox));
      if (!box.isEmpty() && fit) {
        box.getCenter(centre);
        radius = Math.max(4, box.getSize(new three.Vector3()).length() / 2);
      }
      if (fit) look("home");
      else redraw();
    },

    /** Marks one piece as the chosen one, or nothing with null. */
    select(index) {
      if (selected === index) return;
      selected = index;
      group.children.forEach((mesh, i) => {
        mesh.material.emissive.set(i === index ? 0x2a6bff : 0x000000);
        mesh.material.emissiveIntensity = i === index ? 0.3 : 0;
      });
      redraw();
    },

    /**
     * The draggable rings and magnets, as circles lying on the piece. Each is `{ pick, x, y, z, radius, colour }`;
     * `pick` comes back from `onPick` and `onDrag`.
     */
    setHandles(list) {
      empty(handleGroup);
      handles = list.map((item) => {
        const geometry = new three.RingGeometry(Math.max(0.3, item.radius - 0.45), item.radius, 36);
        const mesh = new three.Mesh(
          geometry,
          new three.MeshBasicMaterial({
            color: new three.Color(item.colour ?? "#2a6bff"),
            transparent: true,
            opacity: item.active ? 0.95 : 0.45,
            depthTest: false,
            side: three.DoubleSide,
          }),
        );
        mesh.position.set(item.x, item.y, item.z);
        mesh.renderOrder = 5;
        handleGroup.add(mesh);
        return { ...item, mesh };
      });
      redraw();
    },

    /** A card or a phone laid flat beside the keyring, for scale. */
    setGuide(name) {
      empty(guideGroup);
      const guide = SIZE_GUIDES[name];
      if (guide) {
        const half = [guide.width / 2, guide.height / 2];
        const outline = new three.BufferGeometry().setFromPoints([
          new three.Vector3(-half[0], -half[1], 0),
          new three.Vector3(half[0], -half[1], 0),
          new three.Vector3(half[0], half[1], 0),
          new three.Vector3(-half[0], half[1], 0),
          new three.Vector3(-half[0], -half[1], 0),
        ]);
        guideGroup.add(
          new three.Line(outline, new three.LineBasicMaterial({ color: 0x8893a4, transparent: true, opacity: 0.8 })),
        );
        radius = Math.max(radius, Math.hypot(half[0], half[1]));
      }
      redraw();
    },

    clear() {
      empty(group);
      empty(handleGroup);
      redraw();
    },
    look,
    redraw,
    /** The canvas as a picture, for the cover of a saved model. */
    toBlob: (type = "image/png") =>
      new Promise((resolve) => {
        draw(); // the buffer is only guaranteed to hold the picture right after a render
        canvas.toBlob(resolve, type);
      }),
    dispose() {
      disposed = true;
      cancelAnimationFrame(frame);
      resize.disconnect();
      for (const [type, fn] of listeners) canvas.removeEventListener(type, fn);
      canvas.removeEventListener("wheel", wheel);
      empty(group);
      empty(guideGroup);
      empty(handleGroup);
      renderer.dispose();
    },
  };
}

// ---- ui.js ----

// The tool's window: the settings on the left, the keyring on the right.
//
// Every change takes a snapshot for undo, then queues a build. The build is the slow part — real outlines and real
// booleans — so it is debounced, the last good picture stays on screen while the next one is worked out, and a
// failed build says what to change rather than clearing the view. Nothing is fetched and nothing leaves the
// browser except what you ask to be saved.
//
// The font parser and the solid modeller come from Thingport through `library()`, shared with any other tool that
// wants them; the words come from `locales/<code>.json`, which Thingport reads and hands over as `t()`, so nothing
// the window says is buried in here.


/** What each number control runs between, and what one notch of its slider is. Millimetres unless said. */
const RANGES = {
  width: [15, 400, 0.5],
  gap: [0, 10, 0.1],
  lineGap: [0, 50, 0.5],
  stroke: [-1, 3, 0.05],
  infill: [0, 15, 0.25],
  smoothRadius: [0.1, 2, 0.1],
  letterDepth: [0.4, 15, 0.1],
  borderDepth: [0.4, 15, 0.1],
  borderWidth: [0.4, 6, 0.1],
  base: [0.4, 30, 0.1],
  bridge: [0.6, 8, 0.1],
  clearance: [0, 0.8, 0.05],
  letterTopSize: [0, 3, 0.1],
  borderTopSize: [0, 3, 0.1],
  bottomBevelSize: [0, 3, 0.1],
  magnetDiameterGap: [0, 0.8, 0.05],
  magnetDepthGap: [0, 0.8, 0.05],
  magnetRibSize: [0, 0.4, 0.01],
};

/** The settings panels, in the order the chooser lists them. */
const SECTIONS = ["letters", "shape", "colours", "rings", "magnets"];

const clone = (value) => JSON.parse(JSON.stringify(value));
const round = (value, places = 1) => Number(value.toFixed(places));
const escapeHtml = (text) =>
  String(text ?? "").replace(
    /[&<>"']/g,
    (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character],
  );

export default async function mount(thingport) {
  const { root, theme, t, size, onResize, storage, models, collections, ui, download, library, tool } = thingport;
  const shell = root.querySelector("#krg-shell");
  const $ = (id) => root.querySelector(`#krg-${id}`);

  for (const [name, value] of Object.entries({
    bg: theme.background,
    panel: theme.paper,
    divider: theme.divider,
    text: theme.text,
    muted: theme.textSecondary,
    accent: theme.primary,
    // What reads on the accent, which Thingport picks per accent colour: white for most, dark for the light ones
    // like amber. The fallback keeps an older Thingport, which didn't hand it over, close to right.
    "accent-ink": theme.primaryContrast ?? "#ffffff",
    danger: theme.error,
    warning: theme.warning,
    success: theme.success,
    font: theme.fontFamily,
  })) {
    shell.style.setProperty(`--${name}`, value);
  }

  /** A keyring's name from what it says, so a saved model isn't called the same thing every time. */
  const titleFor = (text) => {
    const line = normalizeText(text).split("\n").join(" ").trim();
    if (!line) return t("notes.untitled");
    // "Keyring" on a keyring shouldn't come out as "Keyring keyring".
    return line.toLowerCase() === t("notes.untitled").toLowerCase() ? line : t("notes.name", { text: line });
  };

  /** An engine refusal in the user's own language, falling back to the English it came with. */
  const reason = (error) => (error?.code ? t(`error.${error.code}`, error.vars) : error?.message || String(error));

  // ---- what the window is showing ------------------------------------------------------------------------------

  let state = { ...clone(DEFAULTS), colours: clone(DEFAULT_COLOURS), fontId: "pt-sans", guide: "none" };
  let fonts = null;
  let font = null;
  let fontLabel = "";
  let manifold = null;
  let result = null; // the last build that worked
  let fresh = false; // whether that build matches the settings
  let section = "letters";
  let activeHole = 0;
  let activeMagnet = 0;
  let editing = null; // "holes" | "magnets" while something is being dragged about
  let picked = null;
  let failure = null;
  let busy = false;
  let revision = 0;
  let onBuilt = null; // an open dialog waiting to refresh itself
  const past = [];
  const future = [];
  const ownFonts = new Map();
  let timer = 0;
  let dead = false;

  const viewer = createViewer(await library("three"), $("canvas"), {
    onPick: (pick) => {
      picked = pick;
      viewer?.select(pick && pick.kind !== "handle" ? pick.index : null);
      if (pick?.kind === "handle") {
        if (pick.of === "holes") activeHole = pick.index;
        else activeMagnet = pick.index;
        if (section === (pick.of === "holes" ? "rings" : "magnets")) renderSheet();
      }
      showReadout();
    },
    onDrag: (pick, point, finished) => {
      if (pick.kind !== "handle" || !result) return;
      if (finished) {
        queue();
        return;
      }
      if (!point) return;
      const frame = result.placement;
      const halfWidth = Math.max(0.001, (frame.max[0] - frame.min[0]) / 2);
      const halfHeight = Math.max(0.001, (frame.max[1] - frame.min[1]) / 2);
      const cx = (frame.min[0] + frame.max[0]) / 2;
      const cy = (frame.min[1] + frame.max[1]) / 2;
      const target = pick.of === "holes" ? state.holes[pick.index] : state.magnets[pick.index];
      if (!target) return;
      target.x = Math.max(-1.6, Math.min(1.6, (point.x - cx) / halfWidth));
      target.y = Math.max(-1.6, Math.min(1.6, (point.y - cy) / halfHeight));
    },
  });

  // ---- keeping and undoing -------------------------------------------------------------------------------------

  const KEY = "keyring";
  const persist = () => {
    storage.set(KEY, { state, section }).catch(() => {}); // a full store shouldn't stop the tool
  };
  const checkpoint = () => {
    past.push(clone(state));
    if (past.length > 40) past.shift();
    future.length = 0;
    syncHistory();
  };
  const syncHistory = () => {
    $("undo").disabled = !past.length;
    $("redo").disabled = !future.length;
  };
  const step = (from, to) => {
    const snapshot = from.pop();
    if (!snapshot) return;
    to.push(clone(state));
    state = snapshot;
    syncHistory();
    renderAll();
    queue();
  };

  // ---- the build -----------------------------------------------------------------------------------------------

  const setState = (name, text) => {
    const pill = $("state");
    pill.dataset.state = name;
    pill.textContent = text;
  };
  const showBusy = (on, text = t("state.working")) => {
    busy = on;
    $("busy").hidden = !on;
    $("busy-text").textContent = text;
  };

  const queue = (delay = 220) => {
    fresh = false;
    persist();
    clearTimeout(timer);
    timer = setTimeout(build, delay);
  };

  async function build() {
    if (dead || !font || !manifold) return;
    const mine = ++revision;
    const doing = result ? t("state.working") : t("state.buildingFirst");
    setState("working", doing);
    showBusy(true, doing);
    // One turn of the event loop, so the spinner is actually painted before the modeller takes the thread.
    await new Promise((resolve) => requestAnimationFrame(resolve));
    if (mine !== revision || dead) return;
    try {
      const built = buildModel(font, manifold, state, flattenPath);
      if (mine !== revision || dead) return;
      result = built;
      failure = null;
      fresh = true;
      state.textScale = built.textScale;
      // The engine slides a magnet that fell outside the piece back in; keep where it put it.
      if (state.magnetEnabled) {
        built.magnets.forEach((magnet, i) => {
          if (!state.magnets[i]) return;
          state.magnets[i].x = magnet.normalizedX;
          state.magnets[i].y = magnet.normalizedY;
        });
      }
      if (!state.widthLocked) state.width = round(built.size[0]);
      $("stop").hidden = true;
      showModel();
      setState("ready", built.connected ? t("state.ready") : t("state.readyInPieces"));
      persist();
      onBuilt?.();
    } catch (error) {
      if (mine !== revision || dead) return;
      failure = reason(error);
      fresh = false;
      $("stop-text").textContent = failure;
      $("stop").hidden = false;
      setState("error", t("state.checkSettings"));
      onBuilt?.();
    } finally {
      if (mine === revision && !dead) showBusy(false);
    }
  }

  // ---- drawing it ----------------------------------------------------------------------------------------------

  const slotColour = (model) => palette(state.colours)[colourSlot(model, state.colours)];
  // While a ring or magnet is being placed the letters go faint, so the piece underneath can be seen.
  const ghosted = (model) => Boolean(editing) && model.kind === "letter";

  function showModel(fit = true) {
    if (!result || !viewer) return;
    viewer.show(result.models, { colourOf: slotColour, hiddenOf: ghosted, fit });
    viewer.setGuide(state.guide);
    showHandles();
    const [width, height, depth] = result.size;
    $("dims").innerHTML = `<b>${width.toFixed(1)} × ${height.toFixed(1)} × ${depth.toFixed(1)}</b> mm`;
    const count = result.models.length;
    $("parts").innerHTML = `<b>${count}</b> ${count === 1 ? t("bar.piece") : t("bar.pieces")}`;
    showReadout();
  }

  function showHandles() {
    if (!viewer) return;
    if (!result || !editing) {
      viewer.setHandles([]);
      return;
    }
    const top = result.effectiveBase + state.borderDepth + 0.3;
    const list =
      editing === "holes"
        ? result.holes.map((hole, index) => ({
            pick: { kind: "handle", of: "holes", index },
            x: hole.x,
            y: hole.y,
            z: top,
            radius: hole.outer / 2,
            active: index === activeHole,
            colour: theme.primary,
          }))
        : result.magnets.map((magnet, index) => ({
            pick: { kind: "handle", of: "magnets", index },
            x: magnet.x,
            y: magnet.y,
            z: top,
            radius: magnet.diameter / 2,
            active: index === activeMagnet,
            colour: theme.warning,
          }));
    viewer.setHandles(list);
  }

  /** What the chosen piece is, and anything the engine wants to say, over the picture. */
  function showReadout() {
    const host = $("readout");
    const bits = [];
    if (result) {
      if (picked && picked.kind !== "handle") {
        const model = result.models[picked.index];
        if (model) {
          const which = colourName(colourSlot(model, state.colours));
          const what = model.char ? t("view.letter", { char: model.char }) : t("view.borderAndBase");
          bits.push(`<span class="krg-chip">${escapeHtml(what)} · <b>${escapeHtml(which)}</b></span>`);
        }
      }
      if (!result.connected) bits.push(`<span class="krg-chip">⚠ <b>${escapeHtml(t("view.notJoined"))}</b></span>`);
      for (const warning of result.warnings.slice(0, 2))
        bits.push(`<span class="krg-chip">${escapeHtml(warning)}</span>`);
    }
    host.innerHTML = bits.join("");
    host.hidden = !bits.length;
  }

  /** What a filament slot is for, in words. */
  const colourName = (slot) => {
    if (normalizeColours(state.colours).single) return t("notes.colourEverything");
    if (slot === 0) return t("notes.colourBorder");
    if (slot === 1) return t("notes.colourLetters");
    return t("notes.colourExtra", { n: slot - 1 });
  };

  // ---- little bits of form -------------------------------------------------------------------------------------

  const help = (text) =>
    `<button class="krg-help" type="button" title="${escapeHtml(text)}" aria-label="${escapeHtml(text)}">?</button>`;

  /** A number box with a slider under it, wired to one setting. */
  function control(host, key, label, options = {}) {
    const { get = () => state[key], set = (value) => (state[key] = value), unit = "mm", hint, after } = options;
    const [min, max, stepSize] = [
      options.min ?? RANGES[key]?.[0] ?? 0,
      options.max ?? RANGES[key]?.[1] ?? 100,
      options.step ?? RANGES[key]?.[2] ?? 0.1,
    ];
    const value = get();
    const box = document.createElement("div");
    box.className = "krg-field krg-slider";
    box.innerHTML = `
      <span class="krg-label">${escapeHtml(label)}${hint ? help(hint) : ""}</span>
      <span class="krg-in">
        <input type="number" min="${min}" max="${max}" step="${stepSize}" value="${value}" aria-label="${escapeHtml(label)}">
        <i>${escapeHtml(unit)}</i>
      </span>
      <input type="range" min="${min}" max="${max}" step="${stepSize}" value="${value}" aria-label="${escapeHtml(label)}" tabindex="-1">
      ${after ? `<p class="krg-note">${escapeHtml(after)}</p>` : ""}`;
    const number = box.querySelector('input[type="number"]');
    const slider = box.querySelector('input[type="range"]');
    // One checkpoint for a whole drag, not one per pixel.
    let started = false;
    const begin = () => {
      if (!started) {
        checkpoint();
        started = true;
      }
    };
    const end = () => (started = false);
    const apply = (raw, from) => {
      const next = Number(raw);
      if (!Number.isFinite(next) || next < min || next > max) return;
      begin();
      set(round(next, 2));
      if (from !== number) number.value = raw;
      if (from !== slider) slider.value = raw;
      queue();
    };
    slider.addEventListener("pointerdown", begin);
    slider.addEventListener("input", () => apply(slider.value, slider));
    slider.addEventListener("change", end);
    slider.addEventListener("blur", end);
    number.addEventListener("input", () => apply(number.value, number));
    number.addEventListener("change", () => {
      // An out-of-range figure typed in gets pulled back rather than ignored.
      const next = Math.max(min, Math.min(max, Number(number.value)));
      if (Number.isFinite(next)) apply(next, null);
      else number.value = get();
      end();
    });
    host.append(box);
    return box;
  }

  /** A choice between a few things. */
  function segmented(host, label, options, current, choose, hint) {
    const box = document.createElement("div");
    box.className = "krg-field";
    box.innerHTML = `
      <span class="krg-label">${escapeHtml(label)}${hint ? help(hint) : ""}</span>
      <div class="krg-seg" role="group" aria-label="${escapeHtml(label)}">
        ${options
          .map(
            (option) =>
              `<button type="button" data-value="${escapeHtml(option.value)}" aria-pressed="${option.value === current}">${escapeHtml(option.label)}</button>`,
          )
          .join("")}
      </div>`;
    box.querySelectorAll("button").forEach((button) => {
      button.addEventListener("click", () => {
        if (button.dataset.value === current) return;
        checkpoint();
        choose(button.dataset.value);
        renderSheet();
        queue();
      });
    });
    host.append(box);
    return box;
  }

  /** On or off. */
  function toggle(host, label, on, change, hint) {
    const row = document.createElement("label");
    row.className = "krg-switch";
    row.innerHTML = `<input type="checkbox" ${on ? "checked" : ""}><span>${escapeHtml(label)}</span>${hint ? help(hint) : ""}`;
    const input = row.querySelector("input");
    input.addEventListener("change", () => {
      checkpoint();
      change(input.checked);
      renderSheet();
      queue();
    });
    host.append(row);
    return row;
  }

  const group = (host, title, hint) => {
    const box = document.createElement("div");
    box.className = "krg-group";
    if (title) box.innerHTML = `<h3>${escapeHtml(title)}${hint ? help(hint) : ""}</h3>`;
    host.append(box);
    return box;
  };
  const fields = (host) => {
    const box = document.createElement("div");
    box.className = "krg-fields";
    host.append(box);
    return box;
  };
  const note = (host, text, kind = "note") => {
    const line = document.createElement("p");
    line.className = `krg-${kind}`;
    line.innerHTML = text;
    host.append(line);
    return line;
  };

  // ---- which settings are showing ------------------------------------------------------------------------------

  function renderNav() {
    const select = $("nav");
    select.innerHTML = SECTIONS.map((id) => {
      const count =
        id === "rings" ? state.holes.length : id === "magnets" && state.magnetEnabled ? state.magnets.length : 0;
      return `<option value="${id}" ${id === section ? "selected" : ""}>${escapeHtml(t(`nav.${id}`))}${count ? ` (${count})` : ""}</option>`;
    }).join("");
  }

  const renderAll = () => {
    renderNav();
    renderSheet();
    $("guide").value = state.guide;
  };

  function renderSheet() {
    const host = $("sheet");
    host.replaceChildren();
    const panels = {
      letters: panelLetters,
      shape: panelShape,
      colours: panelColours,
      rings: panelRings,
      magnets: panelMagnets,
    };
    (panels[section] ?? panelLetters)(host);
    renderNav();
  }

  // ---- Letters -------------------------------------------------------------------------------------------------

  const countText = (stats) =>
    t(stats.lines === 1 ? "letters.countOne" : "letters.countMany", {
      characters: stats.characters,
      maxCharacters: MAX_CHARACTERS,
      lines: stats.lines,
      maxLines: MAX_LINES,
    });

  function panelLetters(host) {
    const text = group(host, t("letters.whatItSays"));
    const box = document.createElement("textarea");
    box.className = "krg-text";
    box.id = "krg-textbox";
    box.value = state.text;
    box.rows = 3;
    box.spellcheck = false;
    box.setAttribute("aria-label", t("letters.textLabel"));
    box.style.textAlign = state.align;
    text.append(box);
    const stats = textStats(state.text);
    const counter = note(text, escapeHtml(countText(stats)));
    let typing = 0;
    box.addEventListener("input", () => {
      const limited = limitText(box.value);
      if (limited !== box.value) {
        const at = box.selectionStart;
        box.value = limited;
        box.setSelectionRange(Math.min(at, limited.length), Math.min(at, limited.length));
      }
      // One checkpoint per burst of typing, so undo goes back a word rather than a letter.
      clearTimeout(typing);
      if (!typing) checkpoint();
      typing = setTimeout(() => (typing = 0), 700);
      state.text = box.value;
      counter.textContent = countText(textStats(state.text));
      queue(360);
    });

    segmented(
      text,
      t("letters.align"),
      [
        { value: "left", label: t("letters.alignLeft") },
        { value: "center", label: t("letters.alignCentre") },
        { value: "right", label: t("letters.alignRight") },
      ],
      state.align,
      (value) => (state.align = value),
    );
    if (stats.lines > 1) control(fields(text), "lineGap", t("letters.lineGap"));

    const face = group(host, t("letters.typeface"));
    note(face, t("letters.inUse", { name: `<b>${escapeHtml(fontLabel || t("letters.loading"))}</b>` }));
    const grid = document.createElement("div");
    grid.className = "krg-fonts";
    face.append(grid);
    const all = [
      ...(fonts?.list ?? []).map((item) => ({ ...item, group: t(`font.${item.group}`) })),
      ...[...ownFonts.values()].map((item) => ({ id: item.id, name: item.name, group: t("letters.yours") })),
    ];
    for (const item of all) {
      const card = document.createElement("button");
      card.type = "button";
      card.className = "krg-font";
      card.dataset.font = item.id;
      card.setAttribute("aria-pressed", String(item.id === state.fontId));
      card.innerHTML = `<em>${escapeHtml(item.name)}</em><span>${escapeHtml(item.group)}</span>`;
      card.addEventListener("click", () => {
        if (item.id === state.fontId) return;
        checkpoint();
        state.fontId = item.id;
        useFont(item.id).then(() => queue(0));
        renderSheet();
      });
      grid.append(card);
    }
    showFontSamples(grid);

    const add = document.createElement("button");
    add.type = "button";
    add.className = "krg-btn";
    add.textContent = t("letters.addFont");
    add.addEventListener("click", pickFontFile);
    face.append(add);
    note(face, escapeHtml(t("letters.addFontNote")));

    const sizes = group(host, t("letters.sizeSpacing"));
    toggle(
      sizes,
      t("letters.keepWidth"),
      state.widthLocked,
      (on) => (state.widthLocked = on),
      t("letters.keepWidthHint"),
    );
    const row = fields(sizes);
    control(row, "width", state.widthLocked ? t("letters.width") : t("letters.widthFollows"), {
      set: (value) => {
        state.width = value;
        state.textScale = null; // a width typed in means solve for the letter size again
      },
    });
    control(row, "gap", t("letters.gap"), { hint: t("letters.gapHint") });
    control(row, "stroke", t("letters.stroke"), { hint: t("letters.strokeHint") });
  }

  /** Each typeface's name written in that typeface, once the card is on screen. */
  function showFontSamples(grid) {
    if (!fonts || !("FontFace" in window)) return;
    const seen = new Set();
    const watcher = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        const id = entry.target.dataset.font;
        watcher.unobserve(entry.target);
        if (seen.has(id)) continue;
        seen.add(id);
        const sample = entry.target.querySelector("em");
        const own = ownFonts.get(id);
        const source = own ? Promise.resolve(own.data) : fonts.bytes(id);
        source
          .then(async (data) => {
            const face = new FontFace(`krg-${id}`, data);
            await face.load();
            document.fonts.add(face);
            sample.style.fontFamily = `"krg-${id}", ${theme.fontFamily}`;
          })
          .catch(() => {}); // a sample that won't render just stays in the window's own font
      }
    });
    grid.querySelectorAll(".krg-font").forEach((card) => watcher.observe(card));
  }

  // ---- Shape ---------------------------------------------------------------------------------------------------

  function panelShape(host) {
    const heights = group(host, t("shape.heights"));
    const one = fields(heights);
    control(one, "letterDepth", t("shape.letterDepth"));
    control(one, "borderDepth", t("shape.borderDepth"));
    control(one, "base", t("shape.base"), {
      get: () => effectiveBase(state),
      set: (value) => {
        if (state.magnetEnabled && normalizeMagnets(state).length) {
          state.magnetAutoHeight = false;
          state.magnetBase = value;
        } else state.base = value;
      },
      min: magnetMinimum(state),
      hint: t("shape.baseHint"),
    });

    const border = group(host, t("shape.border"));
    const two = fields(border);
    control(two, "borderWidth", t("shape.borderWidth"), { hint: t("shape.borderWidthHint") });
    control(two, "infill", t("shape.infill"), { hint: t("shape.infillHint") });
    control(two, "bridge", t("shape.bridge"), { hint: t("shape.bridgeHint") });
    toggle(border, t("shape.fillVoids"), state.fillVoids, (on) => (state.fillVoids = on), t("shape.fillVoidsHint"));
    toggle(border, t("shape.smooth"), state.smoothBorder, (on) => (state.smoothBorder = on));
    if (state.smoothBorder) control(fields(border), "smoothRadius", t("shape.smoothRadius"));

    const edges = group(host, t("shape.edges"), t("shape.edgesHint"));
    const applied = edgeSizes(state);
    segmented(
      edges,
      t("shape.bottomEdge"),
      [
        { value: "none", label: t("shape.square") },
        { value: "bevel", label: t("shape.chamfer") },
      ],
      state.borderBevel ? "bevel" : "none",
      (value) => {
        state.borderBevel = value === "bevel";
        if (value === "none") state.bottomBevelSize = 0;
        else if (!state.bottomBevelSize) state.bottomBevelSize = null;
      },
    );
    const three = fields(edges);
    control(three, "letterTopSize", t("shape.letterTop"), {
      get: () => applied.letter,
      set: (value) => (state.letterTopSize = value),
    });
    control(three, "borderTopSize", t("shape.borderTop"), {
      get: () => applied.border,
      set: (value) => (state.borderTopSize = value),
    });
    if (state.borderBevel) {
      control(three, "bottomBevelSize", t("shape.bottomBevel"), {
        get: () => applied.bottom,
        set: (value) => (state.bottomBevelSize = value),
      });
    }
    if (result?.finishing?.edges) {
      const names = { letter: t("shape.edgeLetters"), border: t("shape.edgeBorder"), bottom: t("shape.edgeBottom") };
      const given = Object.entries(result.finishing.edges)
        .filter(([, value]) => value.asked > 0)
        .map(([key, value]) => {
          const name = names[key] ?? key;
          return value.min + 0.001 < value.asked
            ? `${name} ${value.min.toFixed(2)} mm ${t("shape.heldBack", { asked: value.asked.toFixed(2) })}`
            : `${name} ${value.asked.toFixed(2)} mm`;
        });
      if (given.length) note(edges, escapeHtml(t("shape.eased", { list: given.join(" · ") })));
    }
  }

  // ---- Colours -------------------------------------------------------------------------------------------------

  function panelColours(host) {
    const colours = normalizeColours(state.colours);
    state.colours = colours;

    const how = group(host, t("colours.howMany"));
    segmented(
      how,
      t("colours.howMany"),
      [
        { value: "one", label: t("colours.one") },
        { value: "two", label: t("colours.two") },
      ],
      colours.single ? "one" : "two",
      (value) => (state.colours.single = value === "one"),
    );

    if (colours.single) {
      swatch(
        how,
        t("colours.everything"),
        t("colours.everythingHint"),
        colours.border,
        (value) => (state.colours.border = value),
      );
      note(host, escapeHtml(t("colours.oneNote")));
      return;
    }

    const main = group(host, t("colours.theTwo"));
    swatch(
      main,
      t("colours.borderAndBase"),
      t("colours.borderAndBaseHint"),
      colours.border,
      (value) => (state.colours.border = value),
    );
    swatch(
      main,
      t("colours.letters"),
      t("colours.lettersHint"),
      colours.letter,
      (value) => (state.colours.letter = value),
    );

    colours.extras.forEach((extra, i) => {
      const box = group(host, t("colours.extra", { n: i + 1 }));
      toggle(box, t("colours.useIt"), extra.enabled, (on) => (state.colours.extras[i].enabled = on));
      if (!extra.enabled) return;
      swatch(box, t("colours.colour"), "", extra.colour, (value) => (state.colours.extras[i].colour = value));
      segmented(
        box,
        t("colours.whichLetters"),
        [
          { value: "text", label: t("colours.byCharacter") },
          { value: "positions", label: t("colours.byPosition") },
        ],
        extra.mode,
        (value) => (state.colours.extras[i].mode = value),
      );
      if (extra.mode === "text") {
        const field = document.createElement("div");
        field.className = "krg-field";
        field.innerHTML = `<span class="krg-label">${escapeHtml(t("colours.characters"))}${help(t("colours.charactersHint"))}</span>
          <span class="krg-in"><input type="text" value="${escapeHtml(extra.targets)}" placeholder="${escapeHtml(t("colours.charactersPlaceholder"))}" aria-label="${escapeHtml(t("colours.charactersLabel", { n: i + 1 }))}"></span>`;
        const input = field.querySelector("input");
        let typing = 0;
        input.addEventListener("input", () => {
          clearTimeout(typing);
          if (!typing) checkpoint();
          typing = setTimeout(() => (typing = 0), 700);
          state.colours.extras[i].targets = input.value;
          queue(360);
        });
        box.append(field);
        const chosen = targetLetters(extra.targets);
        if (chosen.length) note(box, t("colours.on", { list: `<b>${escapeHtml(chosen.join(" "))}</b>` }));
      } else {
        const letters = [...normalizeText(state.text)]
          .map((character, index) => ({ character, index }))
          .filter((item) => item.character.trim() && item.character !== "\n");
        const row = document.createElement("div");
        row.className = "krg-seg";
        row.setAttribute("role", "group");
        row.setAttribute("aria-label", t("colours.whichLettersLabel", { n: i + 1 }));
        row.style.flexWrap = "wrap";
        row.innerHTML = letters
          .map(
            (item) =>
              `<button type="button" data-index="${item.index}" aria-pressed="${extra.indices.includes(item.index)}" style="flex:0 0 auto;min-width:26px">${escapeHtml(item.character)}</button>`,
          )
          .join("");
        row.querySelectorAll("button").forEach((button) => {
          button.addEventListener("click", () => {
            checkpoint();
            const index = Number(button.dataset.index);
            const held = state.colours.extras[i].indices;
            const at = held.indexOf(index);
            if (at >= 0) held.splice(at, 1);
            else held.push(index);
            renderSheet();
            queue();
          });
        });
        box.append(row);
      }
    });

    const issues = colourIssues(normalizeText(state.text), colours, result?.models);
    if (issues.duplicates.length) {
      note(host, t("colours.bothNamed", { characters: `<b>${escapeHtml(issues.duplicates.join(" "))}</b>` }), "bad");
    }
    if (issues.missing.length) {
      note(host, t("colours.notInText", { characters: `<b>${escapeHtml(issues.missing.join(" "))}</b>` }), "warn");
    }
    note(host, escapeHtml(t("colours.note")));
  }

  function swatch(host, label, hint, value, set) {
    const row = document.createElement("div");
    row.className = "krg-colour";
    row.innerHTML = `<div><strong>${escapeHtml(label)}</strong>${hint ? `<span>${escapeHtml(hint)}</span>` : ""}</div>
      <input class="krg-swatch" type="color" value="${escapeHtml(value)}" aria-label="${escapeHtml(label)}">`;
    const input = row.querySelector("input");
    let started = false;
    input.addEventListener("input", () => {
      if (!started) {
        checkpoint();
        started = true;
      }
      set(input.value);
      if (result) showModel(false);
      persist();
    });
    input.addEventListener("change", () => (started = false));
    host.append(row);
  }

  // ---- Rings ---------------------------------------------------------------------------------------------------

  function panelRings(host) {
    const top = group(host, t("rings.title"), t("rings.hint"));
    const buttons = document.createElement("div");
    buttons.style.display = "flex";
    buttons.style.gap = "6px";
    buttons.innerHTML = `<button class="krg-btn" type="button" id="krg-add-hole">${escapeHtml(t("rings.add"))}</button>`;
    top.append(buttons);
    buttons.querySelector("#krg-add-hole").addEventListener("click", () => {
      checkpoint();
      state.holes.push({
        x: state.holes.length ? 0.94 : -0.94,
        y: 0.2,
        inner: 4,
        outer: 8,
        localJoin: true,
        reinforce: true,
      });
      activeHole = state.holes.length - 1;
      renderSheet();
      queue();
    });
    if (state.holes.length) {
      const place = document.createElement("button");
      place.type = "button";
      place.className = `krg-btn${editing === "holes" ? " krg-btn-on" : ""}`;
      place.textContent = editing === "holes" ? t("rings.stopPlacing") : t("rings.place");
      place.addEventListener("click", () => (editing === "holes" ? stopEditing() : startEditing("holes")));
      buttons.append(place);
    }

    if (!state.holes.length) {
      const empty = document.createElement("div");
      empty.className = "krg-empty";
      empty.innerHTML = `<span>${escapeHtml(t("rings.none"))}</span>`;
      const add = document.createElement("button");
      add.type = "button";
      add.className = "krg-btn krg-btn-main";
      add.textContent = t("rings.addOne");
      add.addEventListener("click", () => buttons.querySelector("#krg-add-hole").click());
      empty.append(add);
      host.append(empty);
      return;
    }

    activeHole = Math.max(0, Math.min(activeHole, state.holes.length - 1));
    state.holes.forEach((hole, i) => {
      const card = document.createElement("div");
      card.className = "krg-card";
      card.dataset.active = String(i === activeHole);
      const spec = t("rings.spec", {
        inner: hole.inner.toFixed(1),
        collar: ((hole.outer - hole.inner) / 2).toFixed(1),
      });
      card.innerHTML = `<div class="krg-card-top">
          <strong>${escapeHtml(t("rings.ring", { n: i + 1 }))}</strong>
          <em>${escapeHtml(spec)}</em>
          <button class="krg-x" type="button" aria-label="${escapeHtml(t("rings.remove", { n: i + 1 }))}">✕</button>
        </div>`;
      card.querySelector(".krg-x").addEventListener("click", (event) => {
        event.stopPropagation();
        checkpoint();
        state.holes.splice(i, 1);
        activeHole = Math.min(activeHole, state.holes.length - 1);
        if (!state.holes.length) stopEditing();
        renderSheet();
        queue();
      });
      card.addEventListener("click", () => {
        if (activeHole === i) return;
        activeHole = i;
        renderSheet();
        showHandles();
      });
      host.append(card);
      if (i !== activeHole) return;
      const row = fields(card);
      control(row, `holeOuter${i}`, t("rings.across"), {
        get: () => hole.outer,
        set: (value) => {
          const ratio = hole.inner / hole.outer;
          hole.outer = value;
          hole.inner = round(value * ratio, 2);
        },
        min: 3,
        max: 25,
        step: 0.5,
      });
      control(row, `holeInner${i}`, t("rings.hole"), {
        get: () => hole.inner,
        set: (value) => (hole.inner = Math.min(value, round(hole.outer * 0.9, 2))),
        min: 1,
        max: 22,
        step: 0.5,
      });
      toggle(
        card,
        t("rings.reinforce"),
        hole.reinforce !== false,
        (on) => (hole.reinforce = on),
        t("rings.reinforceHint"),
      );
    });
    note(host, escapeHtml(t("rings.dragNote")));
  }

  function startEditing(what) {
    editing = what;
    $("editing").hidden = false;
    $("editing-text").textContent = what === "holes" ? t("view.placeRing") : t("view.placeMagnet");
    showModel(false);
    renderSheet();
  }
  function stopEditing() {
    if (!editing) return;
    editing = null;
    $("editing").hidden = true;
    showModel(false);
    renderSheet();
  }

  // ---- Magnets -------------------------------------------------------------------------------------------------

  function panelMagnets(host) {
    const top = group(host, t("magnets.title"), t("magnets.hint"));
    toggle(top, t("magnets.sink"), state.magnetEnabled, (on) => {
      state.magnetEnabled = on;
      if (on && !state.magnets.length) state.magnets = [{ diameter: 6, depth: 2, x: 0, y: 0 }];
    });
    if (!state.magnetEnabled) {
      note(top, escapeHtml(t("magnets.note")));
      return;
    }

    segmented(
      top,
      t("magnets.howItGoesIn"),
      [
        { value: "open", label: t("magnets.fromBack") },
        { value: "embedded", label: t("magnets.midPrint") },
      ],
      state.magnetMode,
      (value) => (state.magnetMode = value),
      t("magnets.howItGoesInHint"),
    );
    note(top, escapeHtml(state.magnetMode === "embedded" ? t("magnets.embeddedNote") : t("magnets.openNote")));

    const list = group(host, t("magnets.which"));
    const add = document.createElement("button");
    add.type = "button";
    add.className = "krg-btn";
    add.textContent = t("magnets.add");
    add.disabled = state.magnets.length >= 6;
    add.addEventListener("click", () => {
      checkpoint();
      const last = state.magnets[state.magnets.length - 1];
      state.magnets.push({ diameter: last?.diameter ?? 6, depth: last?.depth ?? 2, x: 0, y: 0 });
      activeMagnet = state.magnets.length - 1;
      renderSheet();
      queue();
    });
    list.append(add);
    if (state.magnets.length) {
      const place = document.createElement("button");
      place.type = "button";
      place.className = `krg-btn${editing === "magnets" ? " krg-btn-on" : ""}`;
      place.textContent = editing === "magnets" ? t("rings.stopPlacing") : t("rings.place");
      place.addEventListener("click", () => (editing === "magnets" ? stopEditing() : startEditing("magnets")));
      list.append(place);
    }

    activeMagnet = Math.max(0, Math.min(activeMagnet, state.magnets.length - 1));
    normalizeMagnets(state).forEach((magnet, i) => {
      const card = document.createElement("div");
      card.className = "krg-card";
      card.dataset.active = String(i === activeMagnet);
      card.innerHTML = `<div class="krg-card-top">
          <strong>${escapeHtml(t("magnets.magnet", { n: i + 1 }))}</strong>
          <em>${escapeHtml(t("magnets.spec", { diameter: magnet.diameter, depth: magnet.depth }))}</em>
          <button class="krg-x" type="button" aria-label="${escapeHtml(t("magnets.remove", { n: i + 1 }))}">✕</button>
        </div>`;
      card.querySelector(".krg-x").addEventListener("click", (event) => {
        event.stopPropagation();
        checkpoint();
        state.magnets.splice(i, 1);
        activeMagnet = Math.min(activeMagnet, state.magnets.length - 1);
        if (!state.magnets.length) stopEditing();
        renderSheet();
        queue();
      });
      card.addEventListener("click", () => {
        if (activeMagnet === i) return;
        activeMagnet = i;
        renderSheet();
        showHandles();
      });
      host.append(card);
      if (i !== activeMagnet) return;
      const field = document.createElement("div");
      field.className = "krg-field";
      field.innerHTML = `<span class="krg-label">${escapeHtml(t("magnets.yours"))}</span>
        <span class="krg-in"><select aria-label="${escapeHtml(t("magnets.sizeLabel", { n: i + 1 }))}">${MAGNET_SIZES.map(
          ([diameter, depth]) =>
            `<option value="${diameter}x${depth}" ${diameter === magnet.diameter && depth === magnet.depth ? "selected" : ""}>${escapeHtml(t("magnets.spec", { diameter, depth }))}</option>`,
        ).join("")}</select></span>`;
      const select = field.querySelector("select");
      select.addEventListener("change", () => {
        checkpoint();
        const [diameter, depth] = select.value.split("x").map(Number);
        Object.assign(state.magnets[i], { diameter, depth });
        renderSheet();
        queue();
      });
      card.append(field);
      note(
        card,
        t("magnets.pocket", {
          diameter: `<b>${(magnet.diameter + (+state.magnetDiameterGap || 0)).toFixed(2)}</b>`,
          depth: `<b>${(magnet.depth + (+state.magnetDepthGap || 0)).toFixed(2)}</b>`,
        }),
      );
    });

    const fit = group(host, t("magnets.fit"));
    const row = fields(fit);
    control(row, "magnetDiameterGap", t("magnets.extraAcross"), { step: 0.05, hint: t("magnets.extraAcrossHint") });
    control(row, "magnetDepthGap", t("magnets.extraDeep"), { step: 0.05 });
    toggle(fit, t("magnets.ribs"), state.magnetRibs, (on) => (state.magnetRibs = on), t("magnets.ribsHint"));
    if (state.magnetRibs) control(fields(fit), "magnetRibSize", t("magnets.ribSize"), { step: 0.01 });
    toggle(fit, t("magnets.autoBase"), state.magnetAutoHeight !== false, (on) => (state.magnetAutoHeight = on));
    note(
      fit,
      t("magnets.baseNote", {
        min: `<b>${magnetMinimum(state).toFixed(1)}</b>`,
        actual: `<b>${effectiveBase(state).toFixed(1)}</b>`,
      }),
    );
    note(host, escapeHtml(t("magnets.dragNote")));
  }

  // ---- what comes out, asked when a file is wanted -------------------------------------------------------------

  /**
   * The joined/separate choice, as a block a dialog can hold. It changes the model, so a change rebuilds, and
   * `onChange` lets the dialog refresh whatever it shows about the result.
   */
  function outputFields(host, onChange) {
    const box = document.createElement("div");
    box.className = "krg-group";
    box.innerHTML = `<h3>${escapeHtml(t("output.title"))}${help(t("output.hint"))}</h3>`;
    host.append(box);
    const refresh = () => {
      renderSheet();
      queue(0);
      onChange?.();
    };
    const row = (label, on, change, hint) => {
      const line = document.createElement("label");
      line.className = "krg-switch";
      line.innerHTML = `<input type="checkbox" ${on ? "checked" : ""}><span>${escapeHtml(label)}</span>${hint ? help(hint) : ""}`;
      const input = line.querySelector("input");
      input.addEventListener("change", () => {
        checkpoint();
        change(input.checked);
        rebuildOutput();
        refresh();
      });
      box.append(line);
    };
    const rebuildOutput = () => {
      box.replaceChildren();
      box.innerHTML = `<h3>${escapeHtml(t("output.title"))}${help(t("output.hint"))}</h3>`;
      row(t("output.joined"), state.assembled, (on) => (state.assembled = on));
      row(t("output.separate"), state.separate, (on) => (state.separate = on));
      if (state.separate) control(fields(box), "clearance", t("output.clearance"), { hint: t("output.clearanceHint") });
      if (!state.assembled && !state.separate) note(box, escapeHtml(t("output.pickOne")), "bad");
      else if (state.assembled && state.separate) note(box, escapeHtml(t("output.both")));
    };
    rebuildOutput();
    return { valid: () => state.assembled || state.separate };
  }

  // ---- what to print, in words ---------------------------------------------------------------------------------

  /** What to print, as words: the saved model's description, and the text file. `title` is what it's called. */
  function printNotes(title = titleFor(state.text)) {
    const [width, height, depth] = result.size;
    const colours = normalizeColours(state.colours);
    const used = palette(colours);
    const slots = new Map();
    for (const model of result.models) {
      const slot = colourSlot(model, colours);
      if (!slots.has(slot)) slots.set(slot, []);
      slots.get(slot).push(model.char || t("view.borderAndBase"));
    }
    const lines = [
      title,
      "",
      t("notes.says", { text: normalizeText(state.text).replace(/\n/g, " / ") }),
      t("notes.typeface", { name: fontLabel }),
      t("notes.size", { width: width.toFixed(1), height: height.toFixed(1), depth: depth.toFixed(1) }),
      t("notes.build", {
        base: effectiveBase(state).toFixed(1),
        border: state.borderDepth.toFixed(1),
        letters: state.letterDepth.toFixed(1),
      }),
      "",
      t("notes.filaments"),
    ];
    for (const [slot, parts] of [...slots].sort((a, b) => a[0] - b[0])) {
      lines.push(`  ${slot + 1}. ${used[slot]} — ${colourName(slot)}: ${parts.join(" ")}`);
    }
    lines.push(
      "",
      t("notes.printing"),
      `  ${
        state.assembled && !state.separate
          ? t("notes.onePiece")
          : state.separate && !state.assembled
            ? t("notes.apartOnly", { clearance: state.clearance.toFixed(2) })
            : t("notes.bothWays", { clearance: state.clearance.toFixed(2) })
      }`,
      `  ${t("notes.noSupports")}`,
    );
    if (state.magnetEnabled && normalizeMagnets(state).length) {
      const magnets = normalizeMagnets(state);
      lines.push(
        "",
        t("notes.magnets"),
        `  ${t("notes.magnetList", {
          count: magnets.length,
          list: magnets
            .map((magnet) => t("magnets.spec", { diameter: magnet.diameter, depth: magnet.depth }))
            .join(", "),
        })}`,
        `  ${state.magnetMode === "embedded" ? t("notes.magnetEmbedded") : t("notes.magnetOpen")}`,
      );
    }
    if (state.holes.length) {
      lines.push(
        "",
        t("notes.rings"),
        ...state.holes.map(
          (hole, i) =>
            `  ${t("notes.ring", { n: i + 1, inner: hole.inner.toFixed(1), collar: ((hole.outer - hole.inner) / 2).toFixed(1) })}`,
        ),
      );
    }
    if (result.warnings.length)
      lines.push("", t("notes.worthKnowing"), ...result.warnings.map((warning) => `  - ${warning}`));
    if (!result.connected) lines.push("", `  ${t("notes.inPieces")}`);
    lines.push("", t("notes.madeWith", { version: tool.version }));
    return lines.join("\n");
  }

  // ---- the files -----------------------------------------------------------------------------------------------

  /** A file name from what the keyring says, or from whatever it is being saved as. */
  const fileBase = (from = state.text) =>
    (
      normalizeText(from)
        .split("\n")
        .join("-")
        .replace(/[^\w-]+/g, "-")
        .replace(/-+/g, "-")
        .replace(/^-|-$/g, "") || "keyring"
    ).slice(0, 40);

  async function fileFor(kind, named) {
    const base = fileBase(named ?? state.text);
    const options = { separate: state.separate && !state.assembled, title: named?.trim() || titleFor(state.text) };
    if (kind === "3mf") return { name: `${base}.3mf`, data: await threeMf(result.models, state.colours, options) };
    if (kind === "obj") return { name: `${base}.obj`, data: obj(result.models, options) };
    if (kind === "stl") return { name: `${base}.stl`, data: stl(result.models, options) };
    return { name: `${base}-print-notes.txt`, data: printNotes() };
  }

  async function ensureFresh() {
    if (fresh && result) return true;
    if (busy) {
      ui.toast(t("toast.stillWorking"), "info");
      return false;
    }
    clearTimeout(timer);
    await build();
    if (!fresh || !result) {
      ui.toast(failure || t("toast.wontBuildYet"), "error");
      return false;
    }
    return true;
  }

  // ---- menus and dialogs ---------------------------------------------------------------------------------------

  let menu = null;
  const shutMenu = () => {
    menu?.remove();
    menu = null;
    $("download").setAttribute("aria-expanded", "false");
    $("more").setAttribute("aria-expanded", "false");
  };

  /** A menu hung under a button in the top bar. */
  function openMenu(button, items) {
    shutMenu();
    menu = document.createElement("div");
    menu.className = "krg-menu";
    menu.setAttribute("role", "menu");
    menu.innerHTML = items
      .map((item) =>
        item
          ? `<button type="button" role="menuitem" data-pick="${escapeHtml(item.id)}"><span>${escapeHtml(item.label)}${
              item.note ? `<small>${escapeHtml(item.note)}</small>` : ""
            }</span></button>`
          : "<hr>",
      )
      .join("");
    const box = button.getBoundingClientRect();
    const shellBox = shell.getBoundingClientRect();
    menu.style.top = `${box.bottom - shellBox.top + 5}px`;
    menu.style.right = `${shellBox.right - box.right}px`;
    shell.append(menu);
    button.setAttribute("aria-expanded", "true");
    menu.querySelectorAll("button").forEach((entry) => {
      entry.addEventListener("click", () => {
        const chosen = items.find((item) => item && item.id === entry.dataset.pick);
        shutMenu();
        chosen?.go();
      });
    });
    menu.querySelector("button")?.focus();
  }

  /** A dialog over the window. `build(body, close)` fills it; it returns the element. */
  function openDialog(title, fill) {
    const cover = document.createElement("div");
    cover.className = "krg-cover";
    cover.innerHTML = `<div class="krg-dialog" role="dialog" aria-modal="true" aria-labelledby="krg-dialog-title">
        <div class="krg-dialog-top">
          <h2 id="krg-dialog-title">${escapeHtml(title)}</h2>
          <button class="krg-x" type="button" data-shut aria-label="${escapeHtml(t("save.close"))}">✕</button>
        </div>
        <div class="krg-dialog-body"></div>
        <div class="krg-dialog-foot"></div>
      </div>`;
    shell.append(cover);
    const close = () => {
      onBuilt = null;
      cover.remove();
    };
    cover.querySelectorAll("[data-shut]").forEach((button) => button.addEventListener("click", close));
    cover.addEventListener("pointerdown", (event) => {
      if (event.target === cover) close();
    });
    cover.addEventListener("keydown", (event) => {
      if (event.key === "Escape") close();
    });
    fill(cover.querySelector(".krg-dialog-body"), cover.querySelector(".krg-dialog-foot"), close);
    return cover;
  }

  const footButton = (foot, label, main = false) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `krg-btn${main ? " krg-btn-main" : ""}`;
    button.textContent = label;
    foot.append(button);
    return button;
  };

  // ---- downloading ---------------------------------------------------------------------------------------------

  const FORMATS = [
    { id: "3mf", label: () => t("file.3mf"), note: () => t("file.3mfNote") },
    { id: "obj", label: () => t("file.obj"), note: () => t("file.objNote") },
    { id: "stl", label: () => t("file.stl"), note: () => t("file.stlNote") },
    null,
    { id: "notes", label: () => t("file.notes"), note: () => t("file.notesNote") },
  ];

  $("download").addEventListener("click", () => {
    if (menu) {
      shutMenu();
      return;
    }
    openMenu(
      $("download"),
      FORMATS.map((format) =>
        format ? { id: format.id, label: format.label(), note: format.note(), go: () => askOutput(format.id) } : null,
      ),
    );
  });

  /** What comes out, then the file. The notes aren't geometry, so they skip the question. */
  function askOutput(kind) {
    if (kind === "notes") {
      void handDown(kind);
      return;
    }
    openDialog(t("output.title"), (body, foot, close) => {
      const output = outputFields(body);
      footButton(foot, t("output.cancel")).addEventListener("click", close);
      const go = footButton(foot, t("output.downloadAs", { format: t(`file.${kind}`) }), true);
      const sync = () => (go.disabled = !output.valid());
      onBuilt = sync;
      sync();
      body.addEventListener("change", sync);
      go.addEventListener("click", async () => {
        if (!output.valid()) return;
        close();
        await handDown(kind);
      });
    });
  }

  async function handDown(kind) {
    if (!(await ensureFresh())) return;
    try {
      download(await fileFor(kind));
    } catch (error) {
      ui.toast(error.message || t("toast.fileFailed"), "error");
    }
  }

  // ---- saving it to the library -------------------------------------------------------------------------------

  $("save").addEventListener("click", async () => {
    shutMenu();
    if (!(await ensureFresh())) return;
    const suggested = titleFor(state.text);
    openDialog(t("save.title"), (body, foot, close) => {
      const output = outputFields(body);

      const name = document.createElement("div");
      name.className = "krg-field";
      name.innerHTML = `<span class="krg-label">${escapeHtml(t("save.name"))}</span>
        <span class="krg-in"><input id="krg-save-name" type="text" value="${escapeHtml(suggested)}" aria-label="${escapeHtml(t("save.nameLabel"))}"></span>`;
      body.append(name);
      note(body, escapeHtml(t("save.where")));

      footButton(foot, t("output.cancel")).addEventListener("click", close);
      const go = footButton(foot, t("save.go"), true);
      const nameBox = name.querySelector("input");
      const sync = () => (go.disabled = !output.valid());
      onBuilt = sync;
      sync();
      nameBox.focus();
      nameBox.select();
      nameBox.addEventListener("keydown", (event) => {
        if (event.key === "Enter") go.click();
      });

      go.addEventListener("click", async () => {
        if (!output.valid()) return;
        const chosen = nameBox.value.trim() || suggested;
        go.disabled = true;
        go.textContent = t("save.saving");
        try {
          if (!(await ensureFresh())) throw new Error(failure || t("toast.wontBuildYet"));
          const collection = await collections.pick({ title: t("save.pickCollection") });
          if (!collection) {
            go.disabled = false;
            go.textContent = t("save.go");
            return;
          }
          // What to print goes in the model's own description, where it is read rather than downloaded.
          const model = await models.create({
            name: chosen,
            description: printNotes(chosen),
            tags: ["keyring", "generated"],
            collectionId: collection.id,
            files: [await fileFor("3mf", chosen)],
          });
          const picture = await viewer?.toBlob("image/png");
          if (picture) await models.addImages(model.id, [{ name: `${fileBase(chosen)}.png`, data: picture }]);
          close();
          ui.toast(t("save.done", { name: chosen, collection: collection.name }), "success");
        } catch (error) {
          go.disabled = false;
          go.textContent = t("save.go");
          ui.toast(error.message || t("toast.saveFailed"), "error");
        }
      });
    });
  });

  // ---- the rest of the window ----------------------------------------------------------------------------------

  $("more").addEventListener("click", () => {
    if (menu) {
      shutMenu();
      return;
    }
    openMenu($("more"), [
      {
        id: "reset",
        label: t("bar.startAgain"),
        go: async () => {
          if (!(await ui.confirm({ title: t("bar.startAgainTitle"), message: t("bar.startAgainBody") }))) return;
          checkpoint();
          state = { ...clone(DEFAULTS), colours: clone(DEFAULT_COLOURS), fontId: state.fontId, guide: state.guide };
          renderAll();
          queue(0);
        },
      },
    ]);
  });

  shell.addEventListener("pointerdown", (event) => {
    if (menu && !menu.contains(event.target) && !event.target.closest("#krg-download, #krg-more")) shutMenu();
  });

  $("nav").addEventListener("change", () => {
    section = $("nav").value;
    if (editing && editing !== (section === "rings" ? "holes" : section === "magnets" ? "magnets" : null))
      stopEditing();
    persist();
    renderSheet();
  });
  $("undo").addEventListener("click", () => step(past, future));
  $("redo").addEventListener("click", () => step(future, past));
  $("fit").addEventListener("click", () => viewer?.look("home"));
  $("stop-retry").addEventListener("click", () => queue(0));
  $("editing-done").addEventListener("click", stopEditing);
  $("views")
    .querySelectorAll("button")
    .forEach((button) => {
      button.addEventListener("click", () => {
        $("views")
          .querySelectorAll("button")
          .forEach((other) => other.setAttribute("aria-pressed", String(other === button)));
        viewer?.look(button.dataset.view);
      });
    });
  $("guide").addEventListener("change", () => {
    state.guide = $("guide").value;
    viewer?.setGuide(state.guide);
    persist();
  });

  const keys = (event) => {
    if (!shell.contains(event.target) && event.target !== document.body) return;
    const meta = event.ctrlKey || event.metaKey;
    if (meta && event.key.toLowerCase() === "z") {
      event.preventDefault();
      step(event.shiftKey ? future : past, event.shiftKey ? past : future);
    } else if (event.key === "Escape") {
      if (menu) shutMenu();
      else if (editing) stopEditing();
    }
  };
  window.addEventListener("keydown", keys);

  let last = size;
  onResize((next) => {
    if (next.width !== last.width || next.height !== last.height) viewer?.redraw();
    last = next;
    if (menu) shutMenu();
  });

  // ---- fonts ---------------------------------------------------------------------------------------------------

  async function useFont(id) {
    const own = ownFonts.get(id);
    try {
      if (own) {
        const opentype = await library("opentype");
        font = opentype.parse(own.data.slice(0));
        fontLabel = own.name;
      } else {
        font = await fonts.load(id);
        fontLabel = fonts.list.find((item) => item.id === id)?.name ?? id;
      }
      state.fontId = id;
      if (section === "letters") renderSheet();
      return true;
    } catch (error) {
      ui.toast(t("toast.fontFailed", { error: error.message }), "error");
      return false;
    }
  }

  function pickFontFile() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ".ttf,.otf,font/ttf,font/otf";
    input.addEventListener("change", async () => {
      const file = input.files?.[0];
      if (!file) return;
      if (file.size > 8 * 1024 * 1024) {
        ui.toast(t("toast.fontTooBig"), "error");
        return;
      }
      const data = await file.arrayBuffer();
      const id = `own-${ownFonts.size + 1}`;
      try {
        const opentype = await library("opentype");
        opentype.parse(data.slice(0)); // fail here rather than halfway through a build
      } catch (error) {
        ui.toast(t("toast.notAFont", { error: error.message }), "error");
        return;
      }
      ownFonts.set(id, { id, name: file.name.replace(/\.(ttf|otf)$/i, ""), data });
      checkpoint();
      if (await useFont(id)) {
        renderSheet();
        queue(0);
      }
    });
    input.click();
  }

  // ---- getting going -------------------------------------------------------------------------------------------

  // The window's own words, before anything is loaded.
  for (const [id, text] of [
    ["undo", t("bar.undo")],
    ["redo", t("bar.redo")],
    ["more", t("bar.more")],
    ["fit", t("view.fit")],
    ["editing-done", t("view.done")],
    ["stop-retry", t("state.tryAgain")],
  ]) {
    $(id).setAttribute("aria-label", text);
    $(id).title = text;
  }
  $("undo").title = t("bar.undoHint");
  $("redo").title = t("bar.redoHint");
  $("editing-done").textContent = t("view.done");
  $("stop-retry").textContent = t("state.tryAgain");
  $("download").lastChild.textContent = ` ${t("bar.download")}`;
  $("save").lastChild.textContent = ` ${t("bar.save")}`;
  $("dims").title = t("bar.sizeHint");
  $("parts").title = t("bar.piecesHint");
  $("canvas").setAttribute("aria-label", t("view.canvas"));
  $("views").setAttribute("aria-label", t("view.which"));
  $("stop-title").textContent = t("state.wontBuild");
  setState("idle", t("state.starting"));
  $("nav").setAttribute("aria-label", t("nav.which"));
  $("guide").setAttribute("aria-label", t("view.compare"));
  $("guide").previousElementSibling.textContent = t("view.compare");
  $("guide").parentElement.title = t("view.compare");
  $("views")
    .querySelectorAll("button")
    .forEach((button) => (button.textContent = t(`view.${button.dataset.view}`)));
  for (const [value, key] of [
    ["none", "view.compareNone"],
    ["card", "view.compareCard"],
    ["phone", "view.comparePhone"],
  ]) {
    $("guide").querySelector(`option[value="${value}"]`).textContent = t(key);
  }

  renderNav();
  renderSheet();
  setState("working", t("state.gettingReady"));
  showBusy(true, t("state.gettingReady"));

  try {
    const kept = await storage.get(KEY);
    if (kept?.state) {
      state = { ...clone(DEFAULTS), colours: clone(DEFAULT_COLOURS), fontId: "pt-sans", guide: "none", ...kept.state };
      state.colours = normalizeColours(state.colours);
      if (SECTIONS.includes(kept.section)) section = kept.section;
    }
  } catch {
    // Nothing kept, or it wouldn't read: the first settings do.
  }

  try {
    [fonts, manifold] = await Promise.all([library("fonts"), library("manifold")]);
  } catch (error) {
    showBusy(false);
    setState("error", t("state.couldntStart"));
    $("stop-title").textContent = t("state.modellerFailed");
    $("stop-text").textContent = error.message || String(error);
    $("stop").hidden = false;
    return () => {};
  }

  if (!(await useFont(state.fontId))) await useFont("pt-sans");
  $("guide").value = state.guide;
  renderAll();
  syncHistory();
  await build();

  return () => {
    dead = true;
    revision++;
    clearTimeout(timer);
    window.removeEventListener("keydown", keys);
    shutMenu();
    viewer?.dispose();
  };
}
